static std::string trim(std::string s) {
    auto not_space = [](unsigned char ch) { return !std::isspace(ch); };
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), not_space));
    s.erase(std::find_if(s.rbegin(), s.rend(), not_space).base(), s.end());
    return s;
}

static std::string_view trim_view(std::string_view text);
static unsigned char fold_ascii(unsigned char ch);

static bool native_prose_space(unsigned char ch) {
    // CP437 0x0b/0x0c are the game's male/female glyphs, not prose padding.
    return ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n';
}

static std::string compact_ui_message_literal(std::string_view text) {
    std::string compact;
    compact.reserve(text.size());
    for (unsigned char ch : text)
        if (!native_prose_space(ch)) compact.push_back(fold_ascii(ch));
    return compact;
}

#include "literal_anchor_index.inc"

static std::string lower(std::string s) {
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char ch) {
        return static_cast<char>(std::tolower(ch));
    });
    return s;
}

static std::string lower_native_name(std::string s) {
    // RAW language words and native name fields use CP437. Its accented
    // capitals must match the lowercase roots without losing their accents
    // (for example, Åmurist is åm + urist). Keep this out of generic lower(),
    // which also receives UTF-8 text whose continuation bytes overlap CP437.
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char ch) {
        switch (ch) {
        case 0x80: return static_cast<char>(0x87); // Ç -> ç
        case 0x8e: return static_cast<char>(0x84); // Ä -> ä
        case 0x8f: return static_cast<char>(0x86); // Å -> å
        case 0x90: return static_cast<char>(0x82); // É -> é
        case 0x92: return static_cast<char>(0x91); // Æ -> æ
        case 0x99: return static_cast<char>(0x94); // Ö -> ö
        case 0x9a: return static_cast<char>(0x81); // Ü -> ü
        case 0xa5: return static_cast<char>(0xa4); // Ñ -> ñ
        default: return static_cast<char>(fold_ascii(ch));
        }
    });
    return s;
}

// English utterances use two spaces after sentences; the native word wrapper
// may replace either space with a line break. Normalize only whitespace, never
// punctuation, case, words or repeated syllables.
static std::string normalize_utterance(std::string_view source,
        std::vector<size_t> *origins = nullptr) {
    std::string result;
    if (origins) origins->clear();
    bool space = false;
    size_t space_at = 0;
    for (size_t i = 0; i < source.size(); ++i) {
        const unsigned char ch = source[i];
        if (native_prose_space(ch)) {
            if (!space) space_at = i;
            space = !result.empty();
        } else {
            if (space) {
                result.push_back(' ');
                if (origins) origins->push_back(space_at);
            }
            result.push_back(static_cast<char>(ch));
            if (origins) origins->push_back(i);
            space = false;
        }
    }
    return result;
}

static bool parse_bool(const std::string &value, bool fallback) {
    const std::string v = lower(trim(value));
    if (v == "1" || v == "yes" || v == "true" || v == "on") return true;
    if (v == "0" || v == "no" || v == "false" || v == "off") return false;
    return fallback;
}

static int parse_int(const std::string &value, int fallback) {
    char *end = nullptr;
    errno = 0;
    long parsed = std::strtol(value.c_str(), &end, 10);
    if (errno || end == value.c_str() || *end != '\0') return fallback;
    if (parsed < INT32_MIN || parsed > INT32_MAX) return fallback;
    return static_cast<int>(parsed);
}

static double parse_double(const std::string &value, double fallback) {
    char *end = nullptr;
    errno = 0;
    double parsed = std::strtod(value.c_str(), &end);
    if (errno || end == value.c_str() || *end != '\0' || !std::isfinite(parsed))
        return fallback;
    return parsed;
}

static void log_line(const char *level, const std::string &message) {
    std::lock_guard<std::mutex> lock(g_log_mutex);
    std::error_code ec;
    fs::create_directories(runtime::directory(), ec);
    std::ofstream out(runtime::path("dfcn.log"), std::ios::app);
    if (!out) return;
    const auto now = std::chrono::system_clock::now();
    const std::time_t time = std::chrono::system_clock::to_time_t(now);
    std::tm tm{};
    native_localtime(tm, time);
    out << std::put_time(&tm, "%Y-%m-%d %H:%M:%S") << " [" << level << "] "
        << message << '\n';
}

#include "render_timing.inc"

static void log_translation_state_timing(const TranslationStateTiming &sample) {
    std::ostringstream line;
    line << std::fixed << std::setprecision(2)
         << "Translation lock slow: thread=" << sample.thread_id
         << "; wait_ms=" << sample.wait_ms << "; hold_ms=" << sample.hold_ms
         << "; caller=" << sample.location.file_name << ':' << sample.location.line
         << ' ' << sample.location.function_name
         << "; owner_at_wait=" << sample.owner_at_wait_thread_id
         << ' ' << sample.owner_at_wait_location.file_name << ':'
         << sample.owner_at_wait_location.line << ' '
         << sample.owner_at_wait_location.function_name;
    log_line("WARN", line.str());
}

