// Layout and boundary flags may change in an extension without introducing
// a new word sense. Typed prose, material and template scopes stay separate.
static std::string translation_rule_scope_key(const Rule& rule) {
    std::string key = rule.source;
    if (rule.case_insensitive)
        for (char& ch : key)
            if (ch >= 'A' && ch <= 'Z') ch += 'a' - 'A';
    key.push_back('\0');
    for (bool scoped : {rule.numeric_template, rule.string_template,
            rule.adventure_prose, rule.legends_prose, rule.legends_book_title,
            rule.legends_event_title, rule.legends_participant_relation,
            rule.legends_identity, rule.legends_description_term,
            rule.legends_continuation, rule.item_description_sentence,
            rule.item_description_term, rule.item_description_predicate,
            rule.magical_material_noun, rule.magical_material_qualifier,
            rule.deity_sphere, rule.help_prose, rule.help_objective,
            rule.tooltip_prose, rule.ui_message}) key.push_back(scoped ? '1' : '0');
    return key;
}

// Both grammatical roles are loaded from the same generated vocabulary.
// No renderer-maintained translations or blanket suffix removal belong here.
struct MagicalMaterial {
    std::string noun;
    std::string qualifier;
};
static std::unordered_map<std::string, MagicalMaterial> g_magical_materials;
static size_t g_magical_material_max_bytes = 0;
static std::unordered_set<std::string> g_magical_material_qualifiers;

static const MagicalMaterial *magical_material(std::string_view source) {
    const auto found = g_magical_materials.find(lower(trim(std::string(source))));
    return found == g_magical_materials.end() ? nullptr : &found->second;
}

struct MagicalMaterialMatch {
    const MagicalMaterial *material = nullptr;
    size_t at = 0;
    size_t length = 0;
};

static MagicalMaterialMatch find_magical_material(std::string_view source) {
    MagicalMaterialMatch best;
    if (g_magical_materials.empty()) return best;
    // Scan complete word-bounded phrases, longest first at each position.
    // A phase-qualified name must win over the same liquid without its phase.
    for (size_t begin = 0; begin < source.size();) {
        size_t limit = std::min(source.size(), begin + g_magical_material_max_bytes);
        if (limit < source.size() && source[limit] != ' ') {
            limit = source.rfind(' ', limit);
            if (limit == std::string_view::npos || limit < begin) limit = begin;
        }
        for (size_t end = limit; end > begin;) {
            const auto found = g_magical_materials.find(std::string(source.substr(begin, end - begin)));
            if (found != g_magical_materials.end() && end - begin > best.length) {
                best = {&found->second, begin, end - begin};
                break;
            }
            const size_t space = source.rfind(' ', end - 1);
            if (space == std::string_view::npos || space <= begin) break;
            end = space;
        }
        const size_t space = source.find(' ', begin);
        if (space == std::string_view::npos) break;
        begin = space + 1;
    }
    return best;
}

static bool is_magical_material_qualifier(std::string_view text) {
    return g_magical_material_qualifiers.contains(std::string(text));
}

struct TrieNode {
    std::unordered_map<unsigned char, int> next;
    int rule = -1;
};

enum ProceduralNameRole : uint8_t {
    kNameFrontNoun = 1u << 0,
    kNameRearNoun = 1u << 1,
    kNameFrontAdjective = 1u << 2,
    kNameRearAdjective = 1u << 3,
    kNameFrontPrefix = 1u << 4,
    kNameVerb = 1u << 5,
};

enum class ProceduralNamePartOfSpeech : uint8_t {
    noun,
    adjective,
    verb,
    prefix,
};

struct ProceduralNameMeaning {
    std::string word_id;
    std::string gloss;
    ProceduralNamePartOfSpeech part_of_speech =
        ProceduralNamePartOfSpeech::noun;
    uint8_t roles = 0;
};

// Native T_WORD compounds and their English glosses use one POS grammar to
// select roots, not one rendering: native spellings stay phonetic. Neither
// pronunciation coverage nor unrelated UI terms decide a surname's split.
static int procedural_compound_score(uint8_t front, uint8_t rear) {
    if (!(front & (kNameFrontNoun | kNameFrontAdjective | kNameFrontPrefix | kNameVerb)) ||
        !(rear & (kNameRearNoun | kNameRearAdjective | kNameVerb))) return -1;
    if ((front & kNameFrontNoun) && (rear & kNameRearNoun)) return 60;
    if ((front & (kNameFrontAdjective | kNameFrontPrefix)) && (rear & kNameRearNoun)) return 55;
    if ((front & kNameFrontNoun) && (rear & kNameRearAdjective)) return 50;
    if ((front & kNameFrontNoun) && (rear & kNameVerb)) return 45;
    if ((front & kNameVerb) && (rear & kNameRearNoun)) return 40;
    return 10;
}

static std::string render_procedural_compound(const std::string &front,
        const std::string &rear, uint8_t front_roles, uint8_t rear_roles) {
    // A rear adjective/verb modifies the front noun. Keep noun+noun in raw
    // order, including roots which have both noun and verb forms.
    if ((front_roles & kNameFrontNoun) && !(rear_roles & kNameRearNoun) &&
        (rear_roles & (kNameRearAdjective | kNameVerb))) return rear + front;
    return front + rear;
}

static std::string render_procedural_hyphenated_title(const std::string &adjectives,
        const std::string &modifier, const std::string &head) {
    // The title's explicit noun-noun compound is one head, modified by the
    // preceding adjectives. Native WORD slots and English text share this
    // rendering; ordinary unhyphenated compound surnames keep their grammar.
    std::string result = adjectives;
    if (!result.empty() && !result.ends_with("的")) result += "的";
    return result + modifier + "之" + head;
}

struct LegendsTextPiece {
    std::string target;
    int foreground_rgb = -1;
    int native_x = 0, native_y = 0;
    int box_pixel_x = -1, box_pixel_width = 0, display_y = 0;
    // End of this grammatical piece's supporting normalized source span.
    // A scrolled worldgen continuation can discard fully hidden pieces
    // without guessing translations for the remaining half of a literal/name.
    size_t source_end = 0;
    // Semantic subjects keep their native object identity through Chinese
    // template reordering. The viewport resolves the actual visible link.
    int native_link_type = -1, native_link_id = -1, native_link_subid = -1;
    std::shared_ptr<const TranslationResult> translation_result;
};

struct LegendsTextFlow {
    std::vector<LegendsTextPiece> pieces;
    // Keep the grammatical pieces immutable across font-size/layout retries.
    // Display fragments may split one long inscription or link across rows.
    std::vector<LegendsTextPiece> display_pieces;
    std::vector<std::pair<int, std::string>> source_rows;
    // The complete native paragraph owns layout height. Scrolling selects
    // a window of that stable layout without fitting the whole event into
    // only its currently visible rows.
    int native_first_line = -1, native_total_lines = 0;
    int font_pixels = 0;
    bool fully_translated = true;
    bool laid_out = false;
};

struct NativeTooltipPage;

struct Match {
    int x = 0;
    int y = 0;
    int length = 0;
    int rule = -1;
    std::string target;
    std::string source;
    // Optional shared text box assigned to adjacent prose lines. The source
    // glyph suppression still uses x/length; only translated layout uses this
    // box so wrapped paragraphs keep a stable left edge or center.
    int layout_x = -1;
    int layout_y = -1;
    // Optional exact horizontal pixel box for graphical widgets whose bounds
    // do not exist in DF's logical character grid. This takes precedence over
    // layout_x/layout_length and avoids half-cell centering errors.
    int layout_box_pixel_x = -1;
    int layout_box_pixel_width = 0;
    // Fine vertical adjustment for widgets whose visual centre falls between
    // logical grid rows (notably the mirrored settings tabs).
    int layout_pixel_y = 0;
    // A framed field can move independently of the native source baseline.
    // Half-font normalization still deduplicates its original glyph spans,
    // but must not put an explicitly placed caption back on the old row.
    bool layout_fixed_baseline = false;
    int layout_length = 0;
    bool layout_left = false;
    bool layout_right = false;
    // One native field owns source clearing and the baseline. Its translated
    // terms can occupy both edges, with equal gaps around their separators.
    std::vector<std::string> layout_justified_parts{};
    // Native single-line fields keep their allocation and shared font size.
    // Only these explicit fields may omit a suffix and display an ellipsis.
    bool layout_ellipsize = false;
    // Native field's exclusive right edge in logical columns. Source length
    // owns English glyph suppression, never the translated drawing budget.
    int layout_clip_right = -1;
    // A popup edge restricts visibility without changing the field's layout.
    bool layout_clip_is_occlusion = false;
    // Actual native control/paragraph area in absolute screen pixels. Keep
    // this independent of glyph measurement and per-color placement boxes.
    std::optional<SDL_Rect> layout_native_clip{};
    // Reflowed prose keeps its paragraph viewport independently of the
    // original writer's per-row clipping and caption background textures.
    bool layout_reflowed_paragraph = false;
    // The announcement manager renders ordinary word strings once. Covered
    // page cells can retain half-font flags, but cannot change this native
    // paragraph's baselines or its complete body ownership.
    bool native_announcement_popup = false;
    // A complete multiline control owns the relocated caption's vertical
    // viewport. Its original writer still bounds the horizontal column.
    bool layout_reflowed_control = false;
    // A complete current native list row recovered behind the hover frame.
    // Its exposed bytes have been checked before it enters page layout.
    bool native_hover_background = false;
    // Verified help frame covering this recovered background caption.
    // Source ownership is exposed spans; layout retains the complete draw.
    std::optional<SDL_Rect> native_help_occluder{};
    std::shared_ptr<const std::vector<SDL_Rect>> native_help_background_frames{};
    // A summary row reconstructed from ordered native draws already owns
    // its complete column; physical tail spans only suppress surviving ink.
    bool native_overview_complete_row = false;
    // Tall adventure target cards own their name and status column together.
    bool native_adventure_target_row = false;
    // Animal picker records retain their complete name/count/sex field and
    // shared columns through native half-font and generic page layout.
    bool native_animal_picker_row = false;
    // Embark resources are drawn over the site's final records by native DF.
    // Keep their display section separate from their original source rows.
    bool native_embark_resource = false;
    // Complete native caption box. Picture captions retain pre-tooltip
    // geometry; proven multi-line buttons use it to move text off their
    // overwritten borders. Source spans still own only the original glyphs.
    std::optional<SDL_Rect> native_picture_caption_box{};
    bool native_labor_control = false;
    std::string native_picture_caption_source{};
    // Complete source and group role recovered by the native item reader.
    std::string native_item_caption_source{};
    bool native_item_group_caption = false;
    // Layout ownership is not translation coverage: retain unknown field
    // text in the collection queue even if its display is later ellipsized.
    bool native_hover_untranslated = false;
    // An untranslated help paragraph reserves its matching scope but keeps
    // the game's original glyphs. Its first row carries the whole source for
    // review, independent of the current wrapping width.
    bool native_help_source_only = false;
    std::string native_help_review_source{};
    // A reflowed paragraph uses one shared FreeType pixel size on every line.
    // Zero keeps the normal per-label auto-sizing path.
    int layout_font_pixels = 0;
    // Labels measured as a group must not shrink independently at draw time.
    bool layout_lock_font_pixels = false;
    // Long-form reading can use a taller line box than a native grid row.
    // Source suppression still belongs to x/y/length, not this pixel box.
    int layout_line_height_pixels = 0;
    // A reflowed document can put text on a formerly blank native row. Its
    // color belongs to the document, not that blank cell's unused foreground.
    int layout_foreground_rgb = -1;
    // Optional per-codepoint colors for a reflowed rich-text line. Render as
    // one texture so color boundaries cannot change kerning or the baseline.
    std::vector<int> layout_glyph_foreground_rgb{};
    // Source ownership stays native; a complete rich sentence may render its
    // links in a different order, shared by all of that sentence's source runs.
    std::shared_ptr<LegendsTextFlow> legends_flow{};
    bool legends_flow_owner = false;
    bool native_history_event_row = false;
    // Optional common reference height for a structured table. It is based
    // on the font's stable line metrics, not each value's changing ink box.
    int layout_visual_height_pixels = 0;
    // Some graphical widgets keep their captions in the logical grid only as
    // metadata, then redraw the complete native caption through an unrelated
    // SDL copy site. The final-composite matcher therefore cannot see those
    // bytes and the ordinary glyph hook cannot remove their English pixels.
    // A non-empty box marks the exact logical source area whose foreground
    // pixels must be erased from the finished widget before drawing target.
    int graphical_clear_x = -1;
    int graphical_clear_y = -1;
    int graphical_clear_width = 0;
    int graphical_clear_height = 0;
    // Only a proved, uniformly filled native text body owns every pixel in
    // this box, including old target ink of any foreground colour.
    bool graphical_clear_flat_background = false;
    bool graphical_auto_foreground = false;
    // Native TOP_OF_TEXT/BOTTOM_OF_TEXT are two halves of ONE caption,
    // not repeated text rows. Preserve that identity through page layout.
    bool native_split_text = false;
    bool native_split_duplicate = false;
    int native_split_top_y = 0;
    // A binding belongs to the current settings list, never to another field
    // which happens to occupy the same screen column (including the HUD).
    std::optional<SDL_Rect> native_keybinding_table{};
    // Shared by every output/ownership span of a mixed native field.
    std::shared_ptr<const TranslationResult> translation_result;
    // Widget fields own the logical page supplied by their source reader.
    bool native_help_current_page = false;
    // Only the DFHack source pass may translate or suppress foreign ink.
    bool native_dfhack_foreground = false;
};

