// Native controls advance their cursor by a grid row. Font reference bounds
// describe glyph placement inside that row, never its allocation or whether
// an already translated field may be displayed.
static int native_text_row_height(const graphicst *graphics) {
    return graphics && graphics->tile_pixel_y > 0 ? graphics->tile_pixel_y : 16;
}

struct GlyphTexture {
    struct Tile {
        SDL_Texture *texture = nullptr;
        SDL_Rect bounds{};
    };
    SDL_Texture *texture = nullptr;
    std::vector<Tile> tiles;
    SDL_Renderer *renderer = nullptr;
    int width = 0;
    int height = 0;
    int pixel_size = 0;
    // Keep native layout advance separate from the font reference envelope.
    // Tall ink/cursors never turn one native row into two allocated rows.
    int line_height = 0;
    int font_reference_height = 0;
    int line_offset_y = 0;
    uint64_t last_used = 0;

    SDL_Rect destination(const SDL_Rect &line, bool left, bool /*locked*/) const {
        // The full glyph run owns its drawing area. Font size and bitmap
        // dimensions never depend on the English caption's allocation.
        return {left ? line.x : line.x + (line.w - width) / 2,
            line.y + (line.h - font_reference_height) / 2 + line_offset_y,
            width, height};
    }
    void destroy() {
        for (const Tile &tile : tiles) SDL_DestroyTexture(tile.texture);
        tiles.clear();
        texture = nullptr;
    }
    void draw(SDL_Renderer *renderer, const SDL_Rect &destination,
              Uint8 r, Uint8 g, Uint8 b) const {
        for (const Tile &tile : tiles) {
            SDL_SetTextureColorMod(tile.texture, r, g, b);
            SDL_SetTextureAlphaMod(tile.texture, 255);
            const SDL_Rect placed{destination.x + tile.bounds.x,
                destination.y + tile.bounds.y, tile.bounds.w, tile.bounds.h};
            SDL_RenderCopy(renderer, tile.texture, nullptr, &placed);
        }
    }
};

struct DeferredGlyphCopy {
    SDL_Texture *texture = nullptr;
    SDL_Texture *render_target = nullptr;
    SDL_Rect source{};
    SDL_Rect destination{};
    bool has_source = false;
};

struct NativeBorderTextureState {
    Uint8 r = 255, g = 255, b = 255, alpha = 255;
    SDL_BlendMode blend = SDL_BLENDMODE_NONE;

    bool capture(SDL_Texture *texture) {
        return texture && SDL_GetTextureColorMod(texture, &r, &g, &b) == 0 &&
            SDL_GetTextureAlphaMod(texture, &alpha) == 0 &&
            SDL_GetTextureBlendMode(texture, &blend) == 0;
    }
    bool apply(SDL_Texture *texture) const {
        const int color_result = SDL_SetTextureColorMod(texture, r, g, b);
        const int alpha_result = SDL_SetTextureAlphaMod(texture, alpha);
        const int blend_result = SDL_SetTextureBlendMode(texture, blend);
        return color_result == 0 && alpha_result == 0 && blend_result == 0;
    }
};

// Borrow only this frame's native border glyphs. Their textures already
