static std::string unescape_tsv(std::string_view input, bool *ok) {
    std::string out;
    out.reserve(input.size());
    *ok = true;
    auto hex = [](char ch) -> int {
        if (ch >= '0' && ch <= '9') return ch - '0';
        if (ch >= 'a' && ch <= 'f') return ch - 'a' + 10;
        if (ch >= 'A' && ch <= 'F') return ch - 'A' + 10;
        return -1;
    };
    for (size_t i = 0; i < input.size(); ++i) {
        char ch = input[i];
        if (ch != '\\') {
            out.push_back(ch);
            continue;
        }
        if (++i >= input.size()) {
            *ok = false;
            return out;
        }
        ch = input[i];
        switch (ch) {
        case '\\': out.push_back('\\'); break;
        case 't': out.push_back('\t'); break;
        case 'n': out.push_back('\n'); break;
        case 'r': out.push_back('\r'); break;
        case '#': out.push_back('#'); break;
        case 'x': {
            if (i + 2 >= input.size()) {
                *ok = false;
                return out;
            }
            const int hi = hex(input[i + 1]);
            const int lo = hex(input[i + 2]);
            if (hi < 0 || lo < 0) {
                *ok = false;
                return out;
            }
            out.push_back(static_cast<char>((hi << 4) | lo));
            i += 2;
            break;
        }
        default:
            // Preserve unknown escapes literally so paths remain usable.
            out.push_back('\\');
            out.push_back(ch);
            break;
        }
    }
    return out;
}

static bool decode_utf8(std::string_view text, std::vector<uint32_t> &codepoints) {
    codepoints.clear();
    for (size_t i = 0; i < text.size();) {
        const unsigned char c = static_cast<unsigned char>(text[i]);
        uint32_t cp = 0;
        size_t count = 0;
        if (c < 0x80) {
            cp = c;
            count = 1;
        } else if ((c & 0xe0) == 0xc0) {
            cp = c & 0x1f;
            count = 2;
            if (cp == 0) return false;
        } else if ((c & 0xf0) == 0xe0) {
            cp = c & 0x0f;
            count = 3;
        } else if ((c & 0xf8) == 0xf0) {
            cp = c & 0x07;
            count = 4;
        } else {
            return false;
        }
        if (i + count > text.size()) return false;
        for (size_t j = 1; j < count; ++j) {
            const unsigned char tail = static_cast<unsigned char>(text[i + j]);
            if ((tail & 0xc0) != 0x80) return false;
            cp = (cp << 6) | (tail & 0x3f);
        }
        if ((count == 2 && cp < 0x80) || (count == 3 && cp < 0x800) ||
            (count == 4 && cp < 0x10000) || cp > 0x10ffff ||
            (cp >= 0xd800 && cp <= 0xdfff)) {
            return false;
        }
        codepoints.push_back(cp);
        i += count;
    }
    return true;
}

static std::optional<std::pair<uint32_t, size_t>> decode_utf8_at(
        std::string_view text, size_t offset) {
    if (offset >= text.size()) return std::nullopt;
    const unsigned char first = static_cast<unsigned char>(text[offset]);
    uint32_t codepoint = 0;
    size_t length = 0;
    if (first < 0x80) {
        codepoint = first;
        length = 1;
    } else if ((first & 0xe0) == 0xc0) {
        codepoint = first & 0x1f;
        length = 2;
        if (codepoint == 0) return std::nullopt;
    } else if ((first & 0xf0) == 0xe0) {
        codepoint = first & 0x0f;
        length = 3;
    } else if ((first & 0xf8) == 0xf0) {
        codepoint = first & 0x07;
        length = 4;
    } else {
        return std::nullopt;
    }
    if (offset + length > text.size()) return std::nullopt;
    for (size_t index = 1; index < length; ++index) {
        const unsigned char continuation =
            static_cast<unsigned char>(text[offset + index]);
        if ((continuation & 0xc0) != 0x80) return std::nullopt;
        codepoint = (codepoint << 6) | (continuation & 0x3f);
    }
    if ((length == 2 && codepoint < 0x80) ||
        (length == 3 && codepoint < 0x800) ||
        (length == 4 && codepoint < 0x10000) ||
        codepoint > 0x10ffff ||
        (codepoint >= 0xd800 && codepoint <= 0xdfff)) {
        return std::nullopt;
    }
    return std::pair<uint32_t, size_t>{codepoint, length};
}

static bool is_cjk_display_codepoint(uint32_t codepoint) {
    return (codepoint >= 0x2e80 && codepoint <= 0x33ff) ||
           (codepoint >= 0x3400 && codepoint <= 0x4dbf) ||
           (codepoint >= 0x4e00 && codepoint <= 0x9fff) ||
           (codepoint >= 0xf900 && codepoint <= 0xfaff) ||
           (codepoint >= 0xff00 && codepoint <= 0xffef) ||
           (codepoint >= 0x20000 && codepoint <= 0x323af);
}

static bool contains_cjk_utf8(std::string_view text) {
    for (size_t cursor = 0; cursor < text.size();) {
        const auto decoded = decode_utf8_at(text, cursor);
        if (decoded && is_cjk_display_codepoint(decoded->first)) return true;
        cursor += decoded ? decoded->second : 1;
    }
    return false;
}

// User-entered UTF-8 is not a dictionary translation. Every page, including
// pages that own their entire layout, shares this byte-glyph replacement.
static void append_direct_utf8_matches(const std::string &row, int y,
        std::vector<Match> &matches) {
    for (size_t cursor = 0; cursor < row.size();) {
        const auto decoded = decode_utf8_at(row, cursor);
        if (!decoded || !is_cjk_display_codepoint(decoded->first)) {
            ++cursor;
            continue;
        }
        const size_t start = cursor;
        cursor += decoded->second;
        while (cursor < row.size()) {
            const auto next = decode_utf8_at(row, cursor);
            if (!next || !is_cjk_display_codepoint(next->first)) break;
            cursor += next->second;
        }
        if (!g_logged_direct_utf8_input.exchange(true))
            log_line("INFO", "Detected direct UTF-8 text in the game character grid");
        matches.push_back({static_cast<int>(start), y,
            static_cast<int>(cursor - start), -8,
            row.substr(start, cursor - start), row.substr(start, cursor - start)});
    }
}

