// The native embark item picker draws item names from std::strings before they
// reach the logical character grid. Verified call-site hooks record every string
// at the embark and adventure item-list draw paths; when DF
// shortens a long name, a companion pre-resize hook associates that visible
// text with its complete source. The overlay can therefore translate all
// Available Items categories from the real in-memory source rather than
// reconstructing grid fragments.
static std::mutex g_embark_item_source_mutex;
struct EmbarkItemSourceCapture {
    int screen_x = -1;
    int screen_y = -1;
    std::string visible;
    std::string complete;
    std::chrono::steady_clock::time_point captured_at{};
    uint64_t capture_epoch = 0;
};
static std::unordered_map<uint64_t, EmbarkItemSourceCapture>
    g_embark_item_sources_by_position;
// Position lookup intentionally keeps only one value per cell for ellipsis
// recovery.  Food rows need the complete draw sequence instead: several
// semantic fields can be issued from the same cursor cell in one frame.
static std::vector<EmbarkItemSourceCapture> g_embark_item_fields_this_frame;
static std::atomic<uint64_t> g_embark_item_capture_epoch{1};
#include "unit_identity_sources.inc"
#include "squad_name_sources.inc"
// Generic clipping captures retain exact byte identity, not a prefix lookup.
// Consumers bind complete fields to their current native position and bytes.
struct NativeClippedCaption {
    int x, y;
    std::string visible, complete;
};
static std::mutex g_clipped_caption_mutex;
static uint64_t g_clipped_caption_epoch = 0;
static std::vector<NativeClippedCaption> g_clipped_captions;

static void clear_clipped_captions() {
    std::lock_guard<std::mutex> lock(g_clipped_caption_mutex);
    g_clipped_captions.clear();
    g_clipped_caption_epoch = 0;
}

static void remember_clipped_caption(int x, int y, std::string_view visible,
        std::string_view complete) {
    std::lock_guard<std::mutex> lock(g_clipped_caption_mutex);
    const auto epoch = g_embark_item_capture_epoch.load(std::memory_order_acquire);
    if (epoch != g_clipped_caption_epoch) {
        g_clipped_captions.clear();
        g_clipped_caption_epoch = epoch;
    }
    std::erase_if(g_clipped_captions, [&](const NativeClippedCaption &caption) {
        return caption.x == x && caption.y == y;
    });
    if (g_clipped_captions.size() < 512)
        g_clipped_captions.push_back({x, y, std::string(visible), std::string(complete)});
}

static std::vector<NativeClippedCaption> captured_clipped_captions() {
    std::lock_guard<std::mutex> lock(g_clipped_caption_mutex);
    if (g_clipped_caption_epoch != g_embark_item_capture_epoch.load(std::memory_order_acquire)) return {};
    return g_clipped_captions;
}

// Captured while the real SKILLS text widget and its parent chain are live.
// Retain geometry only; later grid readers never dereference these widgets.
struct NativeUnitChooserRecord {
    SDL_Rect box{}, viewport{}, panel{};
    int skill_x = -1;
    int search_y = -1;
    std::string squad_name_source, squad_caption_source, squad_caption_complete_source;
    std::optional<NativeHistoryName> generated_squad_name;
    std::optional<std::string> squad_alias;
    int squad_position = -1;
    int squad_caption_x = -1, squad_caption_y = -1;
    int unit_identity_x = -1, unit_identity_y = -1;
    std::string unit_identity_source, unit_identity_complete_source, unit_identity_split_source;
    std::optional<std::string> unit_identity_target;
};
static std::mutex g_native_unit_chooser_record_mutex;
static uint64_t g_native_unit_chooser_record_epoch = 0;
static std::vector<NativeUnitChooserRecord> g_native_unit_chooser_records;

static void clear_native_unit_chooser_records() {
    std::lock_guard<std::mutex> lock(g_native_unit_chooser_record_mutex);
    g_native_unit_chooser_records.clear();
    g_native_unit_chooser_record_epoch = 0;
}

static void remember_native_unit_chooser_record(const NativeUnitChooserRecord &record,
        uint64_t epoch) {
    std::lock_guard<std::mutex> lock(g_native_unit_chooser_record_mutex);
    if (epoch != g_embark_item_capture_epoch.load(std::memory_order_acquire)) return;
    if (g_native_unit_chooser_record_epoch != epoch) {
        g_native_unit_chooser_records.clear();
        g_native_unit_chooser_record_epoch = epoch;
    }
    const auto same_rect = [](const SDL_Rect &a, const SDL_Rect &b) {
        return a.x == b.x && a.y == b.y && a.w == b.w && a.h == b.h;
    };
    std::erase_if(g_native_unit_chooser_records, [&](const NativeUnitChooserRecord &other) {
        return same_rect(other.box, record.box) && same_rect(other.viewport, record.viewport) &&
            same_rect(other.panel, record.panel);
    });
    if (g_native_unit_chooser_records.size() < 512)
        g_native_unit_chooser_records.push_back(record);
}

static std::vector<NativeUnitChooserRecord> captured_native_unit_chooser_records() {
    std::lock_guard<std::mutex> lock(g_native_unit_chooser_record_mutex);
    if (g_native_unit_chooser_record_epoch !=
            g_embark_item_capture_epoch.load(std::memory_order_acquire)) return {};
    return g_native_unit_chooser_records;
}
static std::atomic<int> g_embark_capture_screen_dimx{0};
static std::atomic<int> g_embark_capture_screen_dimy{0};
static uint64_t embark_item_position_key(int screen_x, int screen_y) {
    return (static_cast<uint64_t>(static_cast<uint32_t>(screen_y)) << 32) |
        static_cast<uint32_t>(screen_x);
}

static void remember_embark_item_field(int screen_x,
                                       int screen_y,
                                       std::string_view visible,
                                       std::string_view complete) {
    if (visible.empty() || complete.empty()) {
        return;
    }
    const std::string visible_key = lower(trim(std::string(visible)));
    const std::string complete_source = lower(trim(std::string(complete)));
    if (visible_key.empty() || complete_source.empty()) return;

    const uint64_t capture_epoch =
        g_embark_item_capture_epoch.load(std::memory_order_acquire);
    const auto captured_at = std::chrono::steady_clock::now();
    std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
    auto duplicate = std::find_if(
        g_embark_item_fields_this_frame.begin(),
        g_embark_item_fields_this_frame.end(),
        [&](const EmbarkItemSourceCapture &capture) {
            return capture.capture_epoch == capture_epoch &&
                capture.screen_x == screen_x &&
                capture.screen_y == screen_y &&
                capture.visible == visible_key &&
                capture.complete == complete_source;
        });
    if (duplicate != g_embark_item_fields_this_frame.end()) {
        duplicate->captured_at = captured_at;
        return;
    }
    g_embark_item_fields_this_frame.push_back({
        screen_x, screen_y, visible_key, complete_source,
        captured_at, capture_epoch,
    });
}

static void remember_embark_item_source(int screen_x,
                                        int screen_y,
                                        std::string_view visible,
                                        std::string_view complete) {
    if (visible.empty() || complete.empty()) return;
    const uint64_t capture_epoch =
        g_embark_item_capture_epoch.load(std::memory_order_acquire);

    // Item rows are redrawn every frame. Once a position still contains the
    // same two GameStrings, refresh only its lifetime instead of allocating,
    // lower-casing and replacing both strings again. Item names on this screen
    // are already lower case, while the slower normalization path below still
    // handles any exceptional spelling safely.
    if (screen_x >= 0 && screen_y >= 0) {
        const uint64_t position_key =
            embark_item_position_key(screen_x, screen_y);
        std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
        const auto found = g_embark_item_sources_by_position.find(position_key);
        if (found != g_embark_item_sources_by_position.end() &&
            found->second.visible == visible &&
            found->second.complete == complete) {
            found->second.captured_at = std::chrono::steady_clock::now();
            found->second.capture_epoch = capture_epoch;
            return;
        }
    }

    const std::string visible_key = lower(trim(std::string(visible)));
    const std::string complete_source = lower(trim(std::string(complete)));
    if (visible_key.empty() || complete_source.empty()) return;
    {
        std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
        if (screen_x >= 0 && screen_y >= 0) {
            g_embark_item_sources_by_position[
                embark_item_position_key(screen_x, screen_y)] = {
                    screen_x, screen_y, visible_key, complete_source,
                    std::chrono::steady_clock::now(), capture_epoch,
                };
        }
    }
}

static std::optional<std::string> captured_embark_item_source(
        int screen_x, int screen_y, std::string_view visible) {
    if (visible.empty()) return std::nullopt;
    const std::string key = lower(trim(std::string(visible)));
    std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
    const uint64_t capture_epoch =
        g_embark_item_capture_epoch.load(std::memory_order_acquire);
    const auto deadline =
        std::chrono::steady_clock::now() - std::chrono::seconds(2);
    for (auto capture = g_embark_item_sources_by_position.begin();
         capture != g_embark_item_sources_by_position.end();) {
        if (capture->second.captured_at < deadline) {
            capture = g_embark_item_sources_by_position.erase(capture);
        } else {
            ++capture;
        }
    }
    if (screen_x >= 0 && screen_y >= 0) {
        const auto position = g_embark_item_sources_by_position.find(
            embark_item_position_key(screen_x, screen_y));
        if (position != g_embark_item_sources_by_position.end()) {
            const EmbarkItemSourceCapture &capture = position->second;
            if (capture.capture_epoch == capture_epoch &&
                capture.visible == key && !capture.complete.empty())
                return capture.complete;
        }
    }

    // The native graphics cursor is local to the item-list widget on this
    // screen, while find_matches() works in final logical-grid columns. Their
    // y coordinate and visible GameString are shared, but their x coordinates
    // are not. Resolve that horizontal transform by selecting the newest
    // in-memory draw with the same row and exact visible spelling; the caller
    // retains its real final-grid x for suppression and layout.
    const EmbarkItemSourceCapture *newest = nullptr;
    for (const auto &[position_key, capture] :
         g_embark_item_sources_by_position) {
        (void)position_key;
        if (capture.capture_epoch != capture_epoch ||
            capture.screen_y != screen_y || capture.visible != key ||
            capture.complete.empty() || capture.captured_at < deadline) {
            continue;
        }
        if (!newest || capture.captured_at > newest->captured_at)
            newest = &capture;
    }
    if (newest) return newest->complete;

    // Some item families are mirrored through a second widget row whose
    // logical y differs from the native cursor even though the visible
    // GameString is identical. Fall back only when every recent capture with
    // that exact visible spelling resolves to the same complete source. This
    // preserves correctness for colliding ellipsized prefixes while covering
    // every unambiguous material/item combination without category cases.
    std::optional<std::string> unique_complete;
    for (const auto &[position_key, capture] :
         g_embark_item_sources_by_position) {
        (void)position_key;
        if (capture.capture_epoch != capture_epoch ||
            capture.visible != key || capture.complete.empty() ||
            capture.captured_at < deadline) {
            continue;
        }
        if (unique_complete && *unique_complete != capture.complete)
            return std::nullopt;
        unique_complete = capture.complete;
    }
    return unique_complete;
}

static std::vector<EmbarkItemSourceCapture> captured_embark_item_sources() {
    std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
    std::vector<EmbarkItemSourceCapture> captures;
    captures.reserve(g_embark_item_sources_by_position.size());
    const uint64_t capture_epoch =
        g_embark_item_capture_epoch.load(std::memory_order_acquire);
    const auto deadline =
        std::chrono::steady_clock::now() - std::chrono::seconds(2);
    for (auto entry = g_embark_item_sources_by_position.begin();
         entry != g_embark_item_sources_by_position.end();) {
        const EmbarkItemSourceCapture &capture = entry->second;
        if (capture.captured_at < deadline) {
            entry = g_embark_item_sources_by_position.erase(entry);
            continue;
        }
        // Category changes reuse the same item-list coordinates. Only names
        // redrawn since the preceding Present belong to the current list;
        // older entries remain available for ordinary expiry cleanup but must
        // never be injected into a newly selected category.
        if (capture.capture_epoch != capture_epoch) {
            ++entry;
            continue;
        }
        // The position lookup is used only to restore clipped item names.
        if (capture.visible == capture.complete) {
            ++entry;
            continue;
        }
        captures.push_back(capture);
        ++entry;
    }
    return captures;
}

static std::vector<EmbarkItemSourceCapture> captured_embark_item_fields() {
    std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
    const uint64_t capture_epoch =
        g_embark_item_capture_epoch.load(std::memory_order_acquire);
    std::vector<EmbarkItemSourceCapture> captures;
    captures.reserve(g_embark_item_fields_this_frame.size());
    for (const EmbarkItemSourceCapture &capture :
         g_embark_item_fields_this_frame) {
        if (capture.capture_epoch == capture_epoch)
            captures.push_back(capture);
    }
    return captures;
}

static void clear_embark_item_sources() {
    std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
    g_embark_item_sources_by_position.clear();
    g_embark_item_fields_this_frame.clear();
}

static void advance_embark_item_capture_epoch() {
    const uint64_t previous = g_embark_item_capture_epoch.fetch_add(
        1, std::memory_order_acq_rel);
    if (previous == UINT64_MAX) {
        g_embark_item_capture_epoch.store(1, std::memory_order_release);
        clear_embark_item_sources();
    } else {
        std::lock_guard<std::mutex> lock(g_embark_item_source_mutex);
        g_embark_item_fields_this_frame.clear();
    }
}

// Knowledge and adventure species descriptions are assembled as complete std::strings and
// passed to curses_text_boxst::add_paragraph() before DF wraps them into the
// logical character grid.  Keep those original strings, together with the
// exact native wrap output, so the overlay never has to infer prose from a
// clipped or partially scrolled collection of screen rows.
struct NativeParagraphCapture {
    uintptr_t owner = 0;
    int paragraph_width = 0;
    std::string source;
    std::vector<std::string> wrapped_lines;
    uint64_t sequence = 0;
    size_t first_line = 0;
    // Borrowed identities only: never dereference saved row addresses. A
    // current native draw must also supply the exact captured row bytes.
    std::vector<uintptr_t> row_addresses{};
    // Source text is immutable for this capture. Reuse its normalized key
    // across both message passes without re-decoding every historical source.
    std::shared_ptr<const std::string> display_source{};
    // Insertion order is independent of sequence updates on duplicate rows.
    // Candidate indices must retain the original reverse-list traversal.
    uint64_t registry_order = 0;
};
// Overview has its own addst row loop, separate from multiline widgets.
// Its draw call binds the cached wrap output to the sheet's complete quote;
// reading that owner also works when the page does not wrap again.
struct NativeOverviewQuoteDraw {
    uintptr_t owner = 0;
    const unsigned char *grid = nullptr;
    int dimx = 0, dimy = 0;
    int left = 0, right = 0, top = 0, bottom = 0;
    int thoughts_bottom = 0;
    std::string source;
    std::vector<std::string> wrapped_lines;
};
static std::mutex g_native_overview_quote_mutex;
static std::optional<NativeOverviewQuoteDraw> g_native_overview_quote_draw;
static std::atomic_uint64_t g_native_overview_quote_revision{1};
static std::vector<NativeParagraphCapture> captured_native_workshop_requirements();
static int native_workshop_recipe_paragraph_width();
static std::shared_ptr<const std::unordered_set<std::string>> native_mod_workshop_names();

struct NativeParagraphViewport {
    int first_line = -1; // Visible slice within the captured wrap output.
    int total_lines = 0;
};

// Map a complete native paragraph's scroll range onto the complete Chinese
// layout. Both ends are exact, and adjacent native positions must not skip
// any Chinese row. Consumers measure the full document before calling this.
static std::optional<size_t> native_paragraph_window_start(
        const NativeParagraphViewport &viewport, size_t visible_lines, size_t target_lines) {
    if (viewport.first_line < 0 || viewport.total_lines <= 0 || !visible_lines ||
            visible_lines > static_cast<size_t>(viewport.total_lines) ||
            int64_t(viewport.first_line) + int64_t(visible_lines) > viewport.total_lines ||
            target_lines > static_cast<size_t>(INT_MAX)) return std::nullopt;
    const int64_t native_range = viewport.total_lines - int64_t(visible_lines);
    const int64_t target_range = std::max<int64_t>(0, int64_t(target_lines) - int64_t(visible_lines));
    if (!native_range) return target_range ? std::nullopt : std::optional<size_t>(0);
    if (target_range > native_range * int64_t(visible_lines)) return std::nullopt;
    return static_cast<size_t>((int64_t(viewport.first_line) * target_range + native_range / 2) /
        native_range);
}

struct NativeHistoryViewport {
    std::map<int, std::shared_ptr<const NativeHistoryDocument>> rows;
    std::map<uint64_t, std::pair<size_t, size_t>> visible_tokens;
    std::map<uint64_t, NativeParagraphViewport> viewports;
    std::map<int, std::string> gaps;
    size_t draw_count = 0, record_count = 0;
};

static std::mutex g_native_paragraph_mutex;
static std::list<NativeParagraphCapture> g_native_paragraph_captures;
using NativeParagraphKey = std::tuple<uintptr_t, int, size_t>;
using NativeParagraphIndex = std::multimap<NativeParagraphKey,
    decltype(g_native_paragraph_captures)::iterator>;
static NativeParagraphIndex g_native_paragraph_index;
static uint64_t g_native_paragraph_sequence = 0;
static uint64_t g_native_paragraph_registry_order = 0;
struct NativeParagraphRowKey {
    uintptr_t address;
    size_t text_hash;
    bool operator==(const NativeParagraphRowKey &) const = default;
};
struct NativeParagraphRowKeyHash {
    size_t operator()(const NativeParagraphRowKey &key) const noexcept {
        const size_t address = std::hash<uintptr_t>{}(key.address);
        return address ^ (key.text_hash + size_t(0x9e3779b9) +
            (address << 6) + (address >> 2));
    }
};
using NativeParagraphCandidates = std::unordered_set<const NativeParagraphCapture *>;
static std::unordered_map<NativeParagraphRowKey, NativeParagraphCandidates,
    NativeParagraphRowKeyHash> g_native_paragraph_row_index;
static std::unordered_map<uint64_t, NativeParagraphCandidates> g_native_paragraph_prefix_index;
static std::array<size_t, 5> g_native_paragraph_prefix_lengths{};

static uint64_t native_paragraph_prefix(std::string_view source) {
    const size_t length = std::min<size_t>(4, source.size());
    uint64_t key = static_cast<uint64_t>(length) << 32;
    for (size_t at = 0; at < length; ++at)
        key |= static_cast<uint64_t>(static_cast<unsigned char>(source[at])) << (at * 8);
    return key;
}

// Global indices require g_native_paragraph_mutex; reload builds private
// indices before its non-allocating commit. Hashes select a superset only;
// every consumer still proves complete original row bytes and ownership.
static void index_native_paragraph(const NativeParagraphCapture &capture, bool add,
        decltype(g_native_paragraph_row_index) &row_index = g_native_paragraph_row_index,
        decltype(g_native_paragraph_prefix_index) &prefix_index = g_native_paragraph_prefix_index,
        std::array<size_t, 5> &prefix_lengths = g_native_paragraph_prefix_lengths) {
    for (const auto &row : capture.wrapped_lines) {
        const auto anchor = trim_view(row);
        if (anchor.empty()) continue;
        const auto key = native_paragraph_prefix(anchor);
        const size_t length = std::min<size_t>(4, anchor.size());
        if (add) {
            if (prefix_index[key].insert(&capture).second) ++prefix_lengths[length];
        } else if (const auto found = prefix_index.find(key); found != prefix_index.end()) {
            if (found->second.erase(&capture)) --prefix_lengths[length];
            if (found->second.empty()) prefix_index.erase(found);
        }
        break;
    }
    const size_t count = std::min(capture.wrapped_lines.size(), capture.row_addresses.size());
    for (size_t line = 0; line < count; ++line) {
        if (!capture.row_addresses[line] || trim_view(capture.wrapped_lines[line]).empty()) continue;
        const NativeParagraphRowKey key{capture.row_addresses[line],
            std::hash<std::string_view>{}(capture.wrapped_lines[line])};
        if (add) row_index[key].insert(&capture);
        else if (const auto found = row_index.find(key); found != row_index.end()) {
            found->second.erase(&capture);
            if (found->second.empty()) row_index.erase(found);
        }
    }
}

// Retained captures can outnumber the current viewport by thousands. Select
// only possible current draw identities or complete-wrap opening bytes before
// catalog matching. The address path preserves scrolled announcement tails;
// the prefix path preserves every unaddressed/full-source fallback.
template <typename Draw>
static std::vector<const NativeParagraphCapture *> native_paragraph_candidates(
        const std::vector<std::string> &screen_rows,
        const std::vector<Draw> &draws, const std::vector<Draw> &occluded_draws) {
    if (g_native_paragraph_captures.empty()) return {};
    NativeParagraphCandidates selected;
    const auto select_draws = [&](const auto &rows) {
        for (const auto &draw : rows) {
            if (!draw.address) continue;
            const NativeParagraphRowKey key{draw.address,
                std::hash<std::string_view>{}(draw.source)};
            if (const auto found = g_native_paragraph_row_index.find(key);
                    found != g_native_paragraph_row_index.end())
                selected.insert(found->second.begin(), found->second.end());
        }
    };
    select_draws(draws);
    select_draws(occluded_draws);
    std::unordered_set<uint64_t> selected_prefixes;
    for (const auto &row : screen_rows)
        for (size_t x = 0; x < row.size(); ++x) {
            if (row[x] == ' ') continue;
            for (size_t length = 1; length <= 4 && length <= row.size() - x; ++length) {
                if (!g_native_paragraph_prefix_lengths[length]) continue;
                const auto key = native_paragraph_prefix(std::string_view(row).substr(x, length));
                if (const auto found = g_native_paragraph_prefix_index.find(key);
                        found != g_native_paragraph_prefix_index.end() &&
                        selected_prefixes.insert(key).second)
                    selected.insert(found->second.begin(), found->second.end());
            }
        }
    std::vector<const NativeParagraphCapture *> captures(selected.begin(), selected.end());
    std::sort(captures.begin(), captures.end(), [](const auto *left, const auto *right) {
        return left->registry_order > right->registry_order;
    });
    return captures;
}

static bool is_native_prose_source(std::string_view source) {
    if (source.size() < 12 || source.size() > 262144 ||
        source.find('\0') != std::string_view::npos) {
        return false;
    }
    int letters = 0;
    int spaces = 0;
    for (unsigned char ch : source) {
        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z'))
            ++letters;
        else if (ch == ' ')
            ++spaces;
    }
    return letters >= 6 && spaces >= 1;
}

