// Unlike ordinary caption epochs, a reclaim batch starts at the native
// history row loop. Retain its predecessor while the next loop is arriving;
// the grid can still contain the old history beneath a newly drawn list.
struct NativeEmbarkReclaimHistoryDraws {
    const unsigned char *grid = nullptr;
    int dimx = 0, dimy = 0;
    std::vector<NativeDrawnTextRow> rows;
};
static std::mutex g_native_embark_reclaim_history_mutex;
static NativeEmbarkReclaimHistoryDraws g_native_embark_reclaim_history_draws;
static NativeEmbarkReclaimHistoryDraws g_native_embark_reclaim_history_previous_draws;

static std::array<std::vector<NativeDrawnTextRow>, 2> captured_embark_reclaim_history_rows(
        const graphicst &graphics) {
    std::lock_guard<std::mutex> lock(g_native_embark_reclaim_history_mutex);
    std::array<std::vector<NativeDrawnTextRow>, 2> result;
    const std::array batches{&g_native_embark_reclaim_history_draws,
        &g_native_embark_reclaim_history_previous_draws};
    for (size_t i = 0; i < batches.size(); ++i) {
        const auto &batch = *batches[i];
        if (batch.grid == graphics.screen && batch.dimx == graphics.dimx &&
                batch.dimy == graphics.dimy) result[i] = batch.rows;
    }
    return result;
}

static std::shared_ptr<const NativeHistoryDocument> native_embark_reclaim_history_source(
        const std::vector<Match> &paragraph, std::string_view normalized_source,
        const std::array<std::vector<NativeDrawnTextRow>, 2> &batches) {
    if (paragraph.empty()) return {};
    for (const auto &draws : batches) {
        std::shared_ptr<const NativeEmbarkReclaimHistoryParagraph> owner;
        bool complete = true, unavailable = false;
        for (const auto &line : paragraph) {
            const auto found = std::find_if(draws.begin(), draws.end(), [&](const auto &draw) {
                const auto source = trim_view(draw.source);
                if (source.empty()) return false;
                const size_t padding = source.data() - draw.source.data();
                return draw.y == line.y && draw.x + static_cast<int>(padding) == line.x &&
                    source == line.source;
            });
            if (found == draws.end()) { complete = false; break; }
            if (!found->reclaim_history) { unavailable = true; continue; }
            if (owner && owner != found->reclaim_history) { complete = false; break; }
            owner = found->reclaim_history;
        }
        if (!complete) continue;
        // A complete new draw without semantic ownership supersedes the old
        // batch, even when their English happens to be identical.
        if (unavailable) return {};
        if (owner && owner->visible_source == normalized_source) return owner->document;
    }
    return {};
}
