// Search categories select the same grammar as their visible Legends rows.
// Native tab numbers and object layouts stay in the platform adapter.
enum class LegendsSearchKind {
    Figure, Site, Artifact, WrittenContent, Region, Entity, Building,
    Underground, Population
};

// Stockpile display and search share the same typed caption grammar.
// Native stockpile_view_mode numbers belong only to the binding data.
enum class StockpileCaptionKind { Label, Value, Color, Wood, ItemType };

enum class SymbolCaptionKind { Creature, Plant, Shape, Item, Figure, Artifact, Action };

enum class JournalSearchKind {
    Event, Agreement, Person, Site, Group, Region, Creature, Artifact,
    Actor, Organization, Plot, PlotOrganization, Civilization
};

struct NativeModListLayout;
struct CivilizationReferenceCache;

static std::string compact_translated_search_text(std::string_view text) {
    std::string compact;
    compact.reserve(text.size());
    for (size_t cursor = 0; cursor < text.size();) {
        const auto decoded = decode_utf8_at(text, cursor);
        if (!decoded) return {};
        const uint32_t codepoint = decoded->first;
        if (!(codepoint <= 0x7f &&
              std::isspace(static_cast<unsigned char>(codepoint))) &&
            codepoint != 0x3000) {
            compact.append(text.substr(cursor, decoded->second));
        }
        cursor += decoded->second;
    }
    return compact;
}

