    struct FontGlyph {
        FT_Face face = nullptr;
        FT_UInt index = 0;
    };
    struct FontGlyphBitmapKey {
        FT_Face face = nullptr;
        FT_UInt index = 0;
        int pixels = 0;
        bool operator==(const FontGlyphBitmapKey &) const = default;
    };
    struct FontGlyphBitmapKeyHash {
        size_t operator()(const FontGlyphBitmapKey &key) const {
            size_t hash = std::hash<FT_Face>{}(key.face);
            hash ^= std::hash<FT_UInt>{}(key.index) + 0x9e3779b9u +
                (hash << 6) + (hash >> 2);
            hash ^= std::hash<int>{}(key.pixels) + 0x9e3779b9u +
                (hash << 6) + (hash >> 2);
            return hash;
        }
    };
    struct FontGlyphBitmap {
        int advance = 0;
        int left = 0;
        int top = 0;
        unsigned int width = 0;
        unsigned int rows = 0;
        std::vector<unsigned char> coverage;
    };
    struct FontGlyphBitmapCacheEntry {
        std::shared_ptr<const FontGlyphBitmap> bitmap;
        std::list<FontGlyphBitmapKey>::iterator use;
    };
    struct FontLineMetrics {
        int top = 0;
        int bottom = 0;
    };
    struct FontSizeMetrics {
        FontLineMetrics line;
        FontLineMetrics han;
    };
    struct ParagraphGlyphMetrics {
        FT_Face face = nullptr;
        FT_UInt index = 0;
        int advance = 0, left = 0, right = 0, top = 0, bottom = 0;
        bool has_ink = false;
    };
    Config config_;
    // Native formatters only need the on/off decision here. Actual translation
    // still takes TranslationStateScope; this read must not queue behind a
    // whole render pass merely to discover that translation is disabled.
    std::atomic_bool translation_enabled_snapshot_{true};
    // A keyboard choice lasts for this process, including automatic/manual
    // dictionary reloads. Never write it back into the user's config file.
    std::optional<bool> runtime_enabled_override_;
