template <typename Cache>
static TranslationResult cache_native_display_translation(Cache &cache, size_t &bytes,
    const std::string &key, const std::vector<int> &source_colors,
    const std::vector<int> &target_colors, TranslationResult result);

#include "character_thoughts.inc"

const NativeKnowledgeLayout &Overlay::prepare_native_knowledge_layout(
        const std::string &source, int width, bool personality, bool health, bool thoughts,
        bool overview_footer) const {
    // Documents share the native UI size with buttons, labels and popups.
    // Grow the line box around the ink; never resize the font to fit a page.
    const int nominal_font_pixels = unified_font_pixels();
    const uint64_t source_context = native_identity_translation_context();
    const uint64_t resource_revision = RULESETS.resource_revision();
    const auto cached = std::find_if(native_knowledge_layouts_.begin(),
        native_knowledge_layouts_.end(), [&](const NativeKnowledgeLayout &layout) {
            return layout.reusable && layout.source_context == source_context &&
                layout.resource_revision == resource_revision &&
                layout.width == width && layout.personality == personality &&
                layout.health == health && layout.thoughts == thoughts &&
                layout.overview_footer == overview_footer &&
                layout.tile_x == gps_->tile_pixel_x && layout.tile_y == gps_->tile_pixel_y &&
                layout.padding == config_.horizontal_padding &&
                layout.nominal_font_pixels == nominal_font_pixels && layout.source == source;
        });
    if (cached != native_knowledge_layouts_.end()) {
        native_knowledge_layouts_.splice(native_knowledge_layouts_.begin(),
            native_knowledge_layouts_, cached);
        return native_knowledge_layouts_.front();
    }
    {
        NativeKnowledgeLayout next;
        next.source = source;
        next.source_context = source_context;
        next.resource_revision = resource_revision;
        next.width = width;
        next.personality = personality;
        next.health = health;
        next.thoughts = thoughts;
        next.overview_footer = overview_footer;
        next.tile_x = gps_->tile_pixel_x;
        next.tile_y = gps_->tile_pixel_y;
        next.padding = config_.horizontal_padding;
        next.nominal_font_pixels = nominal_font_pixels;
        next.font_pixels = nominal_font_pixels;

        // Read the complete original rich-text string, including paragraphs
        // which have never entered the viewport. [B] and [P] are native
        // paragraph/line controls, not words. Keep inline color tags attached
        // to source bytes until the corresponding translated clauses exist.
        std::vector<std::string> paragraphs;
        std::vector<std::vector<int>> paragraph_foregrounds;
        std::string paragraph;
        std::vector<int> paragraph_colors;
        int current_foreground = -1;
        bool supported_markup = true;
        auto flush = [&] {
            const size_t first = static_cast<size_t>(std::find_if(
                paragraph.begin(), paragraph.end(), [](unsigned char c) {
                    return !std::isspace(c);
                }) - paragraph.begin());
            paragraph = trim(std::move(paragraph));
            if (!paragraph.empty()) {
                paragraph_foregrounds.emplace_back(
                    paragraph_colors.begin() + first,
                    paragraph_colors.begin() + first + paragraph.size());
                paragraphs.push_back(std::move(paragraph));
            }
            paragraph.clear();
            paragraph_colors.clear();
        };
        for (size_t i = 0; i < source.size();) {
            const char ch = source[i];
            if (i + 1 < source.size() &&
                ((ch == '[' && source[i + 1] == '[') ||
                 (ch == ']' && source[i + 1] == ']'))) {
                paragraph.push_back(ch);
                paragraph_colors.push_back(current_foreground);
                i += 2;
                continue;
            }
            if (ch != '[') {
                paragraph.push_back(ch);
                paragraph_colors.push_back(current_foreground);
                ++i;
                continue;
            }
            const size_t end = source.find(']', i + 1);
            if (end == std::string::npos) { supported_markup = false; break; }
            const std::string_view tag(source.data() + i + 1, end - i - 1);
            if (tag == "B" || tag == "P") {
                flush();
            } else if (tag.starts_with("C:") && std::all_of(
                    tag.begin() + 2, tag.end(), [](unsigned char c) {
                        return (c >= '0' && c <= '9') || c == ':';
                    })) {
                if (personality || health || thoughts) {
                    const size_t first = tag.find(':', 2);
                    const size_t second = first == std::string_view::npos
                        ? first : tag.find(':', first + 1);
                    if (first == std::string_view::npos ||
                        second == std::string_view::npos) {
                        supported_markup = false;
                        break;
                    }
                    const int color = parse_int(std::string(tag.substr(2, first - 2)), -1);
                    const int bright = parse_int(std::string(tag.substr(second + 1)), -1);
                    if (color < 0 || color > 7 || bright < 0 || bright > 1) {
                        supported_markup = false;
                        break;
                    }
                    current_foreground = color | (bright ? 64 : 0);
                }
            } else {
                supported_markup = false;
                break;
            }
            i = end + 1;
        }
        flush();

        std::vector<std::string> targets;
        auto document_result = std::make_shared<TranslationResult>();
        document_result->kind = "knowledge";
        document_result->owner = "native knowledge document";
        document_result->resource_revision = RULESETS.resource_revision();
        // UTF-8 byte colors here; converted to codepoint colors for wrapping.
        std::vector<std::vector<int>> target_foregrounds;
        if (supported_markup) {
            std::string whole;
            for (const auto &part : paragraphs) {
                if (!whole.empty()) whole.push_back(' ');
                whole += part;
            }
            // Poetic identity/rules/sections can cross native [B] boundaries.
            // Consume them together, as the existing poetic grammar requires.
            if (personality || health || thoughts) {
                TranslationWorkScope work;
                auto translate_paragraph = [&](const std::string &part) -> TranslationResult {
                    if (thoughts) {
                        return translate_character_thought_paragraph_result(part);
                    }
                    if (health) {
                        auto target = translate_health_description_block(part);
                        return target ? TranslationResult::translated(part, *target, "health")
                            : preserve_native_translation(part, "health");
                    }
                    if (auto need = translate_character_need_sentence(part))
                        return TranslationResult::translated(part, *need, "need");
                    auto translated = translate_personality_facet_paragraph(part);
                    if (!translated || translated->translated_sentence_count < 1)
                        translated = translate_character_preference_paragraph(part);
                    if (translated && translated->translated_sentence_count > 0) {
                        if (translated->passthrough_sentence_count > 0) {
                            log_line("WARN", "Native personality sentence not translated: " +
                                translated->first_passthrough_sentence);
                        }
                        std::string target;
                        for (const auto &sentence : translated->main) target += sentence;
                        for (const auto &sentence : translated->cave_adaptation) target += sentence;
                        auto result = TranslationResult::translated(part, std::move(target), "personality");
                        if (translated->passthrough_sentence_count > 0) {
                            result.status = TranslationStatus::Partial;
                            const auto at = part.find(translated->first_passthrough_sentence);
                            result.fragments.push_back({at == std::string::npos ? 0 : at,
                                at == std::string::npos ? part.size() : at + translated->first_passthrough_sentence.size(),
                                0, result.target.size(), TranslationStatus::Untranslated, "personality sentence"});
                        }
                        return result;
                    }
                    auto target = exact_literal_translation(part);
                    if (!target) target = translate_compositional(part);
                    // A modded/unknown sentence is still reading text. Keep it
                    // whole at the shared document size, never word overlays.
                    return target ? TranslationResult::translated(part, *target, "personality")
                        : preserve_native_translation(part, "personality");
                };
                size_t paragraph_offset = 0;
                for (size_t p = 0; p < paragraphs.size(); ++p) {
                    const auto &part = paragraphs[p];
                    // Each need or thought stays a distinct item, even when
                    // DF packs several sentences into the same rich-text box.
                    const bool needs = personality && (part.starts_with("Overall,") ||
                        is_character_need_entry_source(part));
                    size_t cursor = 0;
                    do {
                        while (cursor < part.size() &&
                               std::isspace(static_cast<unsigned char>(part[cursor]))) ++cursor;
                        const size_t period = needs ? part.find('.', cursor) : std::string::npos;
                        size_t end = thoughts || period == std::string::npos ? part.size() : period + 1;
                        if (thoughts && !work.exhausted()) {
                            try {
                                end = character_thought_sentence_end(part, cursor);
                            } catch (const TranslationWorkLimit &) {
                                if (!work.owns_budget()) throw;
                                // The remaining text is one intact native span
                                // when its next constructor cannot be resolved.
                            }
                        }
                        const std::string item = trim(part.substr(cursor, end - cursor));
                        if (!item.empty()) {
                            const auto &colors = paragraph_foregrounds[p];
                            const int first_color = colors[cursor];
                            const bool uniform = std::all_of(
                                colors.begin() + cursor,
                                colors.begin() + cursor + item.size(),
                                [&](int color) { return color == first_color; });
                            std::string target;
                            std::vector<int> target_colors;
                            TranslationResult item_result;
                            try {
                            if (!work.exhausted()) {
                            std::vector<size_t> semantic_origins;
                            auto semantic_target = thoughts
                                ? translate_character_thought_paragraph(item, &semantic_origins)
                                : health && !uniform
                                ? translate_health_description_block(item, &semantic_origins)
                                : std::optional<std::string>{};
                            if (semantic_target && semantic_origins.size() == semantic_target->size()) {
                                // Reordered events, emotions and attributes
                                // retain their semantic source colors, not a
                                // ratio of the original English line width.
                                target = std::move(*semantic_target);
                                item_result = TranslationResult::translated(item, target,
                                    thoughts ? "thought" : "health", semantic_origins);
                                for (size_t offset : semantic_origins)
                                    target_colors.push_back(colors[cursor + offset]);
                            } else if (thoughts) {
                                // Unknown/modded memories remain complete
                                // reading text too, including their colors.
                                item_result = translate_paragraph(item);
                                target = item_result.target;
                                if (target == cp437_to_utf8(item)) {
                                    for (size_t i = 0; i < item.size(); ++i) {
                                        const auto glyph = cp437_to_utf8(item.substr(i, 1));
                                        target_colors.insert(target_colors.end(), glyph.size(), colors[cursor + i]);
                                    }
                                } else target_colors.assign(target.size(), first_color);
                            } else if (uniform) {
                                item_result = translate_paragraph(item);
                                target = item_result.target;
                                target_colors.assign(target.size(), first_color);
                            } else {
                                // Sentence boundaries and attribute grammar
                                // give semantic source offsets. A color change
                                // is NOT a paragraph break or a width ratio.
                                size_t sentence_begin = 0;
                                while (sentence_begin < item.size()) {
                                    while (sentence_begin < item.size() && std::isspace(
                                        static_cast<unsigned char>(item[sentence_begin])))
                                        ++sentence_begin;
                                    if (sentence_begin == item.size()) break;
                                    const size_t stop = item.find_first_of(".!?", sentence_begin);
                                    const size_t sentence_end = stop == std::string::npos
                                        ? item.size() : stop + 1;
                                    const std::string sentence = item.substr(
                                        sentence_begin, sentence_end - sentence_begin);
                                    std::vector<size_t> origins;
                                    auto translated = stop == std::string::npos
                                        ? std::optional<std::string>{}
                                        : health ? std::optional<std::string>{}
                                        : translate_personality_facet_sentence(
                                            std::string_view(sentence).substr(0, sentence.size() - 1),
                                            &origins);
                                    if (health) translated = translate_health_description_block(sentence, &origins);
                                    if (!translated && personality && stop != std::string::npos)
                                        translated = translate_personality_value_sentence(
                                            std::string_view(sentence).substr(0, sentence.size() - 1),
                                            &origins);
                                    auto sentence_result = translated
                                        ? TranslationResult::translated(sentence, *translated,
                                            health ? "health" : "personality", origins)
                                        : translate_paragraph(sentence);
                                    translated = sentence_result.target;
                                    item_result.append(sentence_result, sentence_begin);
                                    target += *translated;
                                    if (origins.size() == translated->size()) {
                                        for (size_t offset : origins)
                                            target_colors.push_back(colors[
                                                cursor + sentence_begin + offset]);
                                    } else if (*translated == cp437_to_utf8(sentence)) {
                                        // Unknown/modded text stays readable
                                        // without losing its native colors.
                                        for (size_t i = 0; i < sentence.size(); ++i) {
                                            const std::string glyph = cp437_to_utf8(sentence.substr(i, 1));
                                            target_colors.insert(target_colors.end(), glyph.size(),
                                                colors[cursor + sentence_begin + i]);
                                        }
                                    } else {
                                        target_colors.insert(target_colors.end(), translated->size(),
                                            colors[cursor + sentence_begin]);
                                    }
                                    sentence_begin = sentence_end;
                                }
                            }
                            }
                            } catch (const TranslationWorkLimit &) {
                                if (!work.owns_budget()) throw;
                            }
                            if (work.exhausted()) {
                                item_result = preserve_native_translation(item,
                                    thoughts ? "thought" : health ? "health" : "personality", false,
                                    TranslationStatus::WorkLimited);
                                target = item_result.target;
                                target_colors.clear();
                                for (size_t i = 0; i < item.size(); ++i) {
                                    const auto glyph = cp437_to_utf8(item.substr(i, 1));
                                    target_colors.insert(target_colors.end(), glyph.size(), colors[cursor + i]);
                                }
                            }
                            item_result.source = item;
                            item_result.target = target;
                            document_result->append(item_result, paragraph_offset + cursor);
                            targets.push_back(std::move(target));
                            target_foregrounds.push_back(std::move(target_colors));
                        }
                        cursor = end;
                    } while (cursor < part.size());
                    paragraph_offset += part.size() + 1;
                }
            } else if (whole.find(" poetic ") != std::string::npos) {
                // Cross-chapter context has priority. The result adapter
                // falls back only to the native [B] chapter boundaries.
                std::string chapters;
                for (const auto &part : paragraphs) {
                    if (!chapters.empty()) chapters += "[B]";
                    chapters += part;
                }
                auto translated = translate_poetic_form_description_result(chapters);
                if (!translated.usable()) translated = preserve_native_translation(whole, "poetry");
                targets.push_back(translated.target);
                document_result->append(translated);
            } else {
                TranslationWorkScope work;
                size_t source_offset = 0;
                for (const std::string &part : paragraphs) {
                    TranslationResult translated;
                    try {
                        if (auto target = translate_written_work_paragraph(part))
                            translated = TranslationResult::translated(part, *target, "written work");
                        if (!translated.usable()) {
                            auto dance = translate_dance_form_paragraph_result(part, false);
                            auto music = dance.usable() ? TranslationResult{} :
                                translate_musical_form_paragraph_result(part, false);
                            if (dance.usable()) translated = std::move(dance);
                            else if (music.usable()) translated = std::move(music);
                            else {
                                dance = translate_dance_form_paragraph_result(part);
                                music = translate_musical_form_paragraph_result(part);
                                if (dance.changed()) translated = std::move(dance);
                                else if (music.changed()) translated = std::move(music);
                            }
                        }
                    } catch (const TranslationWorkLimit &) {
                        if (!work.owns_budget()) throw;
                        translated = preserve_native_translation(part, "knowledge paragraph", false,
                            TranslationStatus::WorkLimited);
                    }
                    if (!translated.usable()) {
                        const bool notation = part.find('|') != std::string::npos &&
                            std::all_of(part.begin(), part.end(), [](unsigned char c) {
                                return c == '|' || c == 'x' || c == 'X' || c == '-' ||
                                    c == '!' || c == '\'' || c == '`' || std::isspace(c);
                            });
                        translated = preserve_native_translation(part,
                            notation ? "notation" : "knowledge paragraph", notation);
                    }
                    // Every paragraph participates in the same reflow, so
                    // retained English moves with adjacent Chinese text.
                    targets.push_back(translated.target);
                    document_result->append(translated, source_offset);
                    source_offset += part.size() + 1;
                }
            }
            if (document_result->usable()) next.translation_result = document_result;
        }

        const int max_pixels = std::max(1,
            width * gps_->tile_pixel_x - 2 * config_.horizontal_padding - 2);
        auto nonstarter = [](uint32_t cp) {
            switch (cp) {
            case '.': case ',': case '!': case '?': case ':': case ';':
            case ')': case ']': case '}': case 0x3002: case 0x3001:
            case 0xff01: case 0xff1f: case 0xff0c: case 0xff1a: case 0xff1b:
            case 0xff09: case 0x300b: case 0x300d: case 0x300f:
            case 0x3011: case 0x2019: case 0x201d: case 0x2026:
                return true;
            default: return false;
            }
        };
        auto opener = [](uint32_t cp) {
            return cp == '(' || cp == '[' || cp == '{' || cp == 0xff08 ||
                cp == 0x300a || cp == 0x300c || cp == 0x300e ||
                cp == 0x3010 || cp == 0x2018 || cp == 0x201c;
        };
        // Measure every glyph in the complete document, not just the
        // tallest/longest line currently on screen. Cache the actual
        // rendered bitmap bounds: outline metrics can differ by a pixel from
        // rasterize(), which otherwise triggers a second, per-line shrink.
        struct KnowledgeGlyph {
            FT_Face face = nullptr;
            FT_UInt index = 0;
            int advance = 0;
            int left = 0;
            int right = 0;
        };
        std::unordered_map<uint32_t, KnowledgeGlyph> glyphs;
        for (const std::string &target : targets) {
            std::vector<uint32_t> cps;
            if (!decode_utf8(target, cps) || cps.empty()) {
                targets.clear();
                break;
            }
            for (uint32_t cp : cps) glyphs.try_emplace(cp);
        }
        bool font_ready = false;
        if (!targets.empty() && set_font_pixel_size(next.font_pixels)) {
            int ink_top = INT32_MAX;
            int widest_glyph = 0;
            for (auto &[cp, metrics] : glyphs) {
                metrics = {};
                const FontGlyph glyph = resolve_font_glyph(cp, next.font_pixels);
                metrics.face = glyph.face;
                metrics.index = glyph.index;
                const auto bitmap = font_glyph_bitmap(glyph, next.font_pixels);
                if (!bitmap) continue;
                metrics.advance = bitmap->advance;
                if (bitmap->width > 0 && bitmap->rows > 0) {
                    metrics.left = bitmap->left;
                    metrics.right = metrics.left + static_cast<int>(bitmap->width);
                    ink_top = std::min(ink_top, -bitmap->top);
                }
                widest_glyph = std::max(widest_glyph,
                    std::max(metrics.advance, metrics.right) - std::min(0, metrics.left));
            }
            if (ink_top != INT32_MAX && widest_glyph <= max_pixels) {
                next.line_height_pixels = native_text_row_height(gps_);
                font_ready = true;
            }
        }
        if (!font_ready) targets.clear();
        for (size_t target_index = 0; target_index < targets.size(); ++target_index) {
            const std::string &target = targets[target_index];
            std::vector<uint32_t> cps;
            if (!decode_utf8(target, cps) || cps.empty()) {
                next.lines.clear();
                next.line_foregrounds.clear();
                break;
            }
            std::vector<int> foregrounds;
            foregrounds.reserve(cps.size());
            for (size_t i = 0; i < target.size(); ++i) {
                if ((static_cast<unsigned char>(target[i]) & 0xc0) != 0x80)
                    foregrounds.push_back((personality || health || thoughts) ? target_foregrounds[target_index][i] : -1);
            }
            if (!next.lines.empty() && !overview_footer) {
                next.lines.emplace_back();
                next.line_foregrounds.emplace_back();
            }
            size_t start = 0;
            while (start < cps.size()) {
                while (start < cps.size() && cps[start] == ' ') ++start;
                if (start == cps.size()) break;
                size_t end = start;
                size_t last_break = start;
                int pen = 0, ink_left = 0, ink_right = 0;
                FT_UInt previous = 0;
                FT_Face previous_face = nullptr;
                for (; end < cps.size(); ++end) {
                    const KnowledgeGlyph &metrics = glyphs.at(cps[end]);
                    const FT_UInt glyph = metrics.index;
                    if (config_.font_pixel_grid == 0 && previous_face == metrics.face &&
                            FT_HAS_KERNING(metrics.face) && previous && glyph) {
                        FT_Vector delta{};
                        FT_Get_Kerning(metrics.face, previous, glyph, FT_KERNING_DEFAULT, &delta);
                        pen += static_cast<int>(delta.x >> 6);
                    }
                    ink_left = std::min(ink_left, pen + metrics.left);
                    ink_right = std::max(ink_right, pen + metrics.right);
                    pen += metrics.advance;
                    if (std::max(pen, ink_right) - ink_left > max_pixels && end > start) {
                        if (last_break > start) end = last_break;
                        break;
                    }
                    previous = glyph;
                    previous_face = metrics.face;
                    if (end + 1 == cps.size() ||
                        (!nonstarter(cps[end + 1]) && !opener(cps[end]) &&
                         (cps[end] >= 0x80 || cps[end + 1] >= 0x80 || cps[end] == ' ')))
                        last_break = end + 1;
                }
                if (end == start) ++end;
                size_t text_start = start, text_end = end;
                auto whitespace = [](uint32_t cp) {
                    return cp < 0x80 && std::isspace(static_cast<unsigned char>(cp));
                };
                while (text_start < text_end && whitespace(cps[text_start])) ++text_start;
                while (text_end > text_start && whitespace(cps[text_end - 1])) --text_end;
                std::string line;
                for (size_t i = text_start; i < text_end; ++i) append_utf8_codepoint(line, cps[i]);
                next.lines.push_back(std::move(line));
                next.line_foregrounds.emplace_back(
                    foregrounds.begin() + text_start, foregrounds.begin() + text_end);
                start = end;
            }
        }
        next.reusable = source_context == native_identity_translation_context();
        const auto &layout = native_knowledge_layouts_.emplace_front(std::move(next));
        static constexpr size_t maximum_layouts = 16;
        while (native_knowledge_layouts_.size() > maximum_layouts)
            native_knowledge_layouts_.pop_back();
        if (!layout.lines.empty()) {
            log_line("INFO", std::string("Laid out complete native ") +
                (thoughts ? "thoughts" : health ? "health description" : personality ? "personality" : "knowledge") + " document: " +
                std::to_string(layout.lines.size()) + " translated rows, font=" +
                std::to_string(layout.font_pixels) + "px, line height=" +
                std::to_string(layout.line_height_pixels) + "px");
        }
    }
    return native_knowledge_layouts_.front();
}

int Overlay::native_knowledge_required_rows(const std::string &source, int width,
        bool personality, bool health, bool thoughts) const {
    TranslationStateScope translation_scope;
    if (!config_.enabled || !face_ || !gps_ || width <= 0 || width > 768 ||
        gps_->tile_pixel_x <= 0 || gps_->tile_pixel_y <= 0) return 0;
    // Personality ownership comes from its verified native call sites, not
    // words that could also occur in unrelated character-sheet prose.
    if (!personality && !health && !thoughts &&
        !is_native_knowledge_description(source)) return 0;
    const auto &layout = prepare_native_knowledge_layout(source, width, personality, health, thoughts);
    return static_cast<int>((static_cast<int64_t>(layout.lines.size()) *
        layout.line_height_pixels + gps_->tile_pixel_y - 1) / gps_->tile_pixel_y);
}

std::vector<Match> Overlay::embark_pause_menu_matches() const {
    std::vector<Match> result;
    if (!gps_ || !gps_->screen || gps_->dimx <= 0 || gps_->dimx > 1000 ||
        gps_->dimy <= 0 || gps_->dimy > 1000) return result;

    // Read the popup before assigning any background document ownership.
    // The character sheet's captured viewport can overlap the *logical*
    // button/source positions even though the popup is physically centred.
    // Letting the document blank those cells first loses whole captions (or
    // just their suffix) and also feeds soundtrack fragments to the prose fit.
    const std::array<const unsigned char *, 2> layers{{
        gps_->top_in_use ? gps_->screen_top : nullptr, gps_->screen,
    }};
    for (const unsigned char *raw : layers) {
        if (!raw) continue;
        std::vector<std::string> rows(static_cast<size_t>(gps_->dimy),
            std::string(static_cast<size_t>(gps_->dimx), ' '));
        for (int y = 0; y < gps_->dimy; ++y) {
            for (int x = 0; x < gps_->dimx; ++x) {
                const unsigned char ch = raw[
                    (static_cast<size_t>(x) * gps_->dimy + y) * 8];
                rows[static_cast<size_t>(y)][static_cast<size_t>(x)] =
                    ch ? static_cast<char>(ch) : ' ';
            }
        }
        auto locate = [&](std::string_view source) -> std::optional<Match> {
            for (int y = 0; y < gps_->dimy; ++y) {
                const size_t x = rows[static_cast<size_t>(y)].find(source);
                if (x == std::string::npos) continue;
                const auto translated = exact_literal_translation(source);
                if (!translated || translated->empty()) return std::nullopt;
                return Match{static_cast<int>(x), y,
                    static_cast<int>(source.size()), -13, *translated,
                    std::string(source)};
            }
            return std::nullopt;
        };
        auto back = locate("Return to title menu");
        auto resume = locate("Continue");
        // Both action captions must belong to the same live layer and the
        // same small button stack. An unrelated occurrence is not a modal.
        if (!back || !resume || resume->y <= back->y ||
            resume->y - back->y > 10) continue;
        result.push_back(std::move(*back));
        result.push_back(std::move(*resume));
        static constexpr std::array<std::string_view, 5> prefixes{{
            "Track playing: ", "Last track: ", "Interlude playing: ",
            "Last interlude: ", "Combat music: ",
        }};
        for (int y = result[1].y + 1;
             y < std::min(gps_->dimy, result[1].y + 15); ++y) {
            const auto &row = rows[static_cast<size_t>(y)];
            for (std::string_view prefix : prefixes) {
                const size_t x = row.find(prefix);
                if (x == std::string::npos) continue;
                size_t end = x + prefix.size();
                while (end < row.size() &&
                       !is_cp437_box_separator(row, end) &&
                       !(row[end] == ' ' && end + 1 < row.size() &&
                         row[end + 1] == ' ')) ++end;
                const std::string source = trim(row.substr(x, end - x));
                auto translated = exact_literal_translation(source);
                if (!translated) translated = translate_procedural_fragment(source);
                // A new/unknown track must still remain owned by the modal,
                // never by the knowledge paragraph behind it.
                result.push_back({static_cast<int>(x), y,
                    static_cast<int>(source.size()), -13,
                    translated ? *translated : cp437_to_utf8(source), source});
            }
        }
        return result;
    }
    return result;
}

std::vector<Match> Overlay::native_knowledge_matches(
        int only_y, const std::vector<Match> &pause_menu, bool allow_transition) const {
    if (!config_.enabled || !face_ || !gps_) return {};
    if (!native_knowledge_frame_.reusable ||
            native_knowledge_frame_.source_context != native_identity_translation_context() ||
            native_knowledge_frame_.resource_revision != RULESETS.resource_revision()) {
        native_knowledge_frame_ = {};
        native_knowledge_frame_matches_.reset();
        native_knowledge_frame_transition_ = false;
    }
    const std::array<int, 7> geometry{{gps_->dimx, gps_->dimy,
        gps_->tile_pixel_x, gps_->tile_pixel_y, gps_->screen_pixel_x,
        gps_->screen_pixel_y, gps_->top_in_use ? 1 : 0}};
    if (native_knowledge_frame_matches_ && !native_knowledge_frame_matches_->empty() &&
        (native_knowledge_frame_.geometry != geometry ||
         std::any_of(native_knowledge_frame_matches_->begin(),
                     native_knowledge_frame_matches_->end(), [&](const Match &match) {
             return match.x < 0 || match.y < 0 || match.length < 0 ||
                 (match.length == 0 && (!native_knowledge_frame_.document ||
                     !native_knowledge_frame_.document->overview_footer || !match.source.empty())) ||
                 match.y >= gps_->dimy || match.x >= gps_->dimx ||
                 match.length > gps_->dimx - match.x;
         }))) {
        native_knowledge_frame_matches_.reset();
        native_knowledge_frame_transition_ = false;
    }
    // Freeze successful ownership for the SDL frame. Present may retry an
    // early empty result and repair already copied native ink before drawing.
    if (!native_knowledge_frame_matches_) {
        native_knowledge_frame_transition_ = false;
        bool current_draw = false, previous_current = false;
        std::vector<NativeKnowledgeDraw> previous;
        const auto draws = captured_native_knowledge_draws(
            &current_draw, &previous, &previous_current);
        auto matches = resolve_native_knowledge_matches(draws, current_draw, pause_menu);
        if (matches.empty() && !previous.empty())
            matches = resolve_native_knowledge_matches(
                std::move(previous), previous_current, pause_menu);

        const auto &frame = native_knowledge_frame_;
        if (allow_transition && matches.empty() && current_draw && !draws.empty() &&
            frame.document && !frame.document->overview_footer &&
            !frame.matches.empty() && pause_menu.empty() && gps_ &&
            draws.front().document == frame.document &&
            draws.front().x == frame.left && draws.front().y == frame.top &&
            frame.geometry == geometry) {
            // A valid row drawn in this Present interval proves this same
            // document is being rebuilt. Until the new complete viewport is
            // ready, keep the last published Chinese viewport atomically;
            // do not hand its English fragments to generic prose reflow.
            // This is not a timed or text-similarity fallback: an old capture,
            // a different page, or a moved/resized pane cannot take this path.
            int verified = 0;
            for (size_t i = 0; i < draws.size() && i < static_cast<size_t>(frame.height); ++i) {
                const auto &draw = draws[i];
                if (draw.document != frame.document || draw.x != frame.left ||
                    draw.y != frame.top + static_cast<int>(i) ||
                    draw.line != draws.front().line + static_cast<int>(i) || draw.line < 0 ||
                    draw.line >= static_cast<int>(frame.document->rows.size())) break;
                const auto &source = frame.document->rows[static_cast<size_t>(draw.line)];
                int row_bytes = 0;
                bool intact = true;
                for (size_t x = 0; x < source.size() &&
                        x < static_cast<size_t>(frame.document->width); ++x) {
                    if (source[x] == ' ') continue;
                    bool top = false;
                    const size_t tile = static_cast<size_t>(frame.left + x) * gps_->dimy + draw.y;
                    const auto *cell = native_knowledge_draw_owns_base(draw, *gps_)
                        ? gps_->screen + tile * 8
                        : cell_at(frame.left + static_cast<int>(x), draw.y, &top);
                    if (!cell || cell[0] != static_cast<unsigned char>(source[x])) {
                        intact = false;
                        break;
                    }
                    ++row_bytes;
                }
                if (!intact) break;
                verified += row_bytes;
            }
            if (verified >= 12) {
                matches = frame.matches;
                native_knowledge_frame_transition_ = true;
            }
        }
        native_knowledge_frame_matches_ = std::move(matches);
    }
    auto result = *native_knowledge_frame_matches_;
    if (only_y >= 0)
        std::erase_if(result, [only_y](const Match &match) { return match.y != only_y; });
    return result;
}

std::vector<Match> Overlay::resolve_native_knowledge_matches(
        std::vector<NativeKnowledgeDraw> draws, bool current_draw,
        const std::vector<Match> &pause_menu) const {
    std::vector<Match> result;
    if (!config_.enabled || !face_ || !gps_ ||
        gps_->tile_pixel_x <= 0 || gps_->tile_pixel_y <= 0) return result;
    if (draws.empty()) return result;
    std::sort(draws.begin(), draws.end(), [](const auto &a, const auto &b) {
        return a.y < b.y;
    });
    const auto &document = *draws.front().document;
    // Generic wrap captures include character prose after a core reload.
    // Apply the same ownership gate as native_knowledge_required_rows(): an
    // unclassified health paragraph must not evict the health layout cache
    // by being sent to the music/dance grammar on every retained frame.
    if (!document.personality && !document.health && !document.thoughts &&
        !is_native_knowledge_description(document.source)) return result;
    const int left = draws.front().x;
    const int top = draws.front().y;
    const int first_native_line = draws.front().line;
    const int captured_height = static_cast<int>(draws.size());
    int height = captured_height;
    const int width = document.width;
    const std::array<int, 7> geometry{{gps_->dimx, gps_->dimy,
        gps_->tile_pixel_x, gps_->tile_pixel_y, gps_->screen_pixel_x,
        gps_->screen_pixel_y, gps_->top_in_use ? 1 : 0}};
    const auto &frame = native_knowledge_frame_;
    // A scrolling redraw must keep its proven extent while rows arrive.
    // Overview instead owns exactly this complete drawn-box prefix; a prior
    // frame's longer footer must not extend the current source allocation.
    if (!document.overview_footer && frame.document == draws.front().document && frame.left == left &&
        frame.top == top && frame.geometry == geometry) {
        height = std::max(height, frame.height);
    }
    if (left < 0 || top < 0 || width <= 0 || left + width > gps_->dimx ||
        top + height > gps_->dimy || first_native_line < 0 ||
        first_native_line + height > static_cast<int>(document.rows.size())) return result;
    // Blank rows are captured too. This proves the viewport's exact extent
    // without deriving a margin from whichever prose happens to be visible.
    for (int i = 0; i < captured_height; ++i) {
        const auto &draw = draws[static_cast<size_t>(i)];
        if (draw.document != draws.front().document || draw.x != left ||
            draw.y != top + i || draw.line != first_native_line + i) return result;
    }
    // A fresh capture belongs to the actual base writer. Overview also
    // proves retained rows against the current base after buffer rotation.
    // Top artwork does not change which source document was written.
    const bool current_base_draw = (current_draw || document.overview_footer) && gps_->screen &&
        std::all_of(draws.begin(), draws.end(), [&](const NativeKnowledgeDraw &draw) {
            return native_knowledge_draw_owns_base(draw, *gps_);
        });
    // SDL can present the same logical frame without calling addcoloredst
    // again. Its per-copy occlusion bookkeeping is not a page-lifetime signal:
    // checking visible_char_at() alone alternated between this document and
    // the old viewport-dependent paragraph fitter on those retained frames.
    // Reuse only a frame whose actual logical layers and draw geometry are
    // unchanged, not a timed cache or merely a saved native row pointer.
    uint64_t logical_hash = 1469598103934665603ULL;
    auto hash_bytes = [&](const void *data, size_t size) {
        const auto *bytes = static_cast<const unsigned char *>(data);
        for (size_t i = 0; i < size; ++i) {
            logical_hash ^= bytes[i];
            logical_hash *= 1099511628211ULL;
        }
    };
    hash_bytes(geometry.data(), sizeof(geometry));
    // Only this viewport determines whether its text has changed. Hashing
    // the whole fortress made moving creatures, water and the minimap evict
    // an otherwise unchanged document on every frame.
    auto hash_layer = [&](const auto *data, size_t stride) {
        const bool present = data != nullptr;
        hash_bytes(&present, sizeof(present));
        if (!data) return;
        for (int x = left; x < left + width; ++x) {
            const size_t tile = static_cast<size_t>(x) * gps_->dimy + top;
            hash_bytes(data + tile * stride,
                static_cast<size_t>(height) * stride * sizeof(*data));
        }
    };
    hash_layer(gps_->screen, 8);
    hash_layer(gps_->screentexpos, 1);
    if (gps_->top_in_use) {
        hash_layer(gps_->screen_top, 8);
        hash_layer(gps_->screentexpos_top, 1);
        hash_layer(gps_->screentexpos_top_lower, 1);
        hash_layer(gps_->screentexpos_top_anchored, 1);
    }
    const bool retained_frame = frame.document == draws.front().document &&
        frame.logical_hash == logical_hash && frame.left == left &&
        frame.top == top && frame.first_line == first_native_line &&
        frame.height == height;
    // Opening Escape changes the logical layers without necessarily drawing
    // the knowledge rows again. Validate the exposed document against one
    // coherent raw layer, excluding only the proven popup and its widget-local
    // text spans. Do not switch to viewport-dependent reflow just because a
    // menu covered part of an otherwise unchanged document.
    bool paused_document = false;
    if (!retained_frame && pause_menu.size() >= 2 &&
        frame.document == draws.front().document && frame.left == left &&
        frame.top == top && frame.first_line == first_native_line &&
        frame.height == height) {
        const int menu_left = std::max(0, gps_->dimx / 2 - 37);
        const int menu_right = std::min(gps_->dimx, gps_->dimx / 2 + 37);
        const int menu_top = std::max(0, pause_menu[0].y - 10);
        const int menu_bottom = std::min(gps_->dimy, pause_menu[1].y + 15);
        const std::array<const unsigned char *, 2> layers{{
            gps_->screen, gps_->top_in_use ? gps_->screen_top : nullptr,
        }};
        for (const unsigned char *raw : layers) {
            if (!raw) continue;
            int verified = 0;
            bool intact = true;
            for (int i = 0; intact && i < height; ++i) {
                const auto &source = document.rows[static_cast<size_t>(first_native_line + i)];
                for (size_t x = 0; x < source.size() && x < static_cast<size_t>(width); ++x) {
                    const unsigned char expected = static_cast<unsigned char>(source[x]);
                    if (expected == ' ') continue;
                    const int screen_x = left + static_cast<int>(x);
                    const int screen_y = top + i;
                    if (screen_x >= menu_left && screen_x < menu_right &&
                        screen_y >= menu_top && screen_y < menu_bottom) continue;
                    if (std::any_of(pause_menu.begin(), pause_menu.end(),
                        [&](const Match &caption) {
                            return screen_y == caption.y && screen_x >= caption.x &&
                                screen_x < caption.x + caption.length;
                        })) continue;
                    const size_t tile = static_cast<size_t>(screen_x) * gps_->dimy + screen_y;
                    if (raw[tile * 8] != expected) {
                        intact = false;
                        break;
                    }
                    ++verified;
                }
            }
            if (intact && verified >= 12) {
                paused_document = true;
                break;
            }
        }
    }
    int visible_bytes = 0;
    for (int i = 0; !retained_frame && !paused_document && i < height; ++i) {
        const auto &source = document.rows[static_cast<size_t>(first_native_line + i)];
        for (size_t x = 0; x < source.size() && x < static_cast<size_t>(width); ++x) {
            const unsigned char expected = static_cast<unsigned char>(source[x]);
            // Native black-background spaces are transparent; the string
            // terminator also does not clear the remainder of its box. Only
            // actual source ink can prove or disprove document ownership.
            if (expected == ' ') continue;
            // Verify fresh writes against their actual buffer, rather than
            // rejecting base text because unrelated top artwork owns cell_at.
            // Source identity and foreground occlusion are separate concerns.
            bool top_layer = false;
            const size_t tile = static_cast<size_t>(left + x) * gps_->dimy + top + i;
            const auto *cell = current_base_draw ? gps_->screen + tile * 8
                : cell_at(left + static_cast<int>(x), top + i, &top_layer);
            const unsigned char actual = cell && cell[0] ? cell[0] : ' ';
            if (actual != expected) return result;
            if (expected != ' ') ++visible_bytes;
        }
    }
    if (!current_draw && !retained_frame && !paused_document && visible_bytes < 12)
        return result;
    std::string overview_source;
    const std::string *layout_source = &document.source;
    if (document.overview_footer) {
        // Overview draws only complete boxes that fit below its quote. The
        // source vector also contains boxes that DF did not draw this time.
        // Select a complete source prefix by its original box boundaries;
        // a partly arriving box never becomes a truncated grammar input.
        if (first_native_line != 0) return result;
        size_t source_end = 0;
        for (const auto &boundary : document.box_boundaries) {
            if (boundary.native_row_end == static_cast<size_t>(captured_height))
                source_end = boundary.source_end;
        }
        if (!source_end || source_end > document.source.size()) return result;
        overview_source = document.source.substr(0, source_end);
        layout_source = &overview_source;
    }
    const auto &layout = prepare_native_knowledge_layout(
        *layout_source, width, document.personality, document.health, document.thoughts,
        document.overview_footer);
    if (layout.lines.empty()) return result;

    int display_height = height;
    if (document.overview_footer) {
        // Overview has no scrollbar. Its native rows prove source ownership;
        // the actual footer's remaining blank space supplies the Chinese
        // budget without changing that source extent or its retained hash.
        if (first_native_line != 0) return result;
        const auto bottom = character_overview_display_bottom(left, top, width, height);
        if (!bottom) return result;
        display_height = *bottom - top;
        if (display_height < height ||
            int64_t(layout.lines.size()) * layout.line_height_pixels >
                int64_t(display_height) * gps_->tile_pixel_y) return result;
    }
    // Map the native scrollbar's entire range to the complete Chinese
    // document, with exact top/bottom endpoints. Never compact just the
    // currently visible paragraphs: that changed both spacing and translation
    // ownership whenever one source row entered or left the viewport.
    const int native_range = std::max(0, static_cast<int>(document.rows.size()) - height);
    const int visible_lines = display_height * gps_->tile_pixel_y / layout.line_height_pixels;
    if (visible_lines <= 0) return result;
    const int target_range = std::max(0,
        static_cast<int>(layout.lines.size()) - visible_lines);
    const int target_start = !document.overview_footer && native_range > 0
        ? static_cast<int>((static_cast<int64_t>(first_native_line) * target_range +
                            native_range / 2) / native_range) : 0;
    int clip_left = left, clip_right = left + width;
    for (const auto &draw : draws) {
        clip_left = std::max(clip_left,
            static_cast<int>(std::clamp<int64_t>(draw.clip[0], 0, gps_->dimx)));
        clip_right = std::min(clip_right,
            static_cast<int>(std::clamp<int64_t>(draw.clip[1], -1, gps_->dimx - 1) + 1));
    }
    if (clip_left >= clip_right) return result;
    const int origin_x = (gps_->screen_pixel_x - gps_->dimx * gps_->tile_pixel_x) / 2;
    const int origin_y = (gps_->screen_pixel_y - gps_->dimy * gps_->tile_pixel_y) / 2;
    // Taller Chinese lines cross native source-row boundaries. Keep the
    // proven document viewport, including its retained extent during a new
    // draw prefix; a source row's writer clip must not cut its target line.
    const SDL_Rect document_clip{origin_x + clip_left * gps_->tile_pixel_x,
        origin_y + top * gps_->tile_pixel_y,
        (clip_right - clip_left) * gps_->tile_pixel_x, display_height * gps_->tile_pixel_y};
    for (int row = 0; row < display_height; ++row) {
        const int y = top + row;
        // Every native row remains suppressed, even when it lies between two
        // taller Chinese lines. Only the row containing a line's pixel top
        // owns its texture; the following native rows must not draw it again.
        const int line = (row * gps_->tile_pixel_y + layout.line_height_pixels - 1) /
            layout.line_height_pixels;
        const int pixel_top = line * layout.line_height_pixels;
        const int target_line = target_start + line;
        const bool owns_line = line < visible_lines &&
            pixel_top < (row + 1) * gps_->tile_pixel_y &&
            target_line < static_cast<int>(layout.lines.size());
        // Extra Chinese slots own placement only. They must never suppress
        // a source byte or pretend that DF drew a longer native document.
        const bool source_row = row < height;
        Match match{left, y, source_row ? width : 0, kNativeKnowledgeDocumentRule,
            owns_line ? layout.lines[static_cast<size_t>(target_line)] : std::string{},
            source_row ? document.rows[static_cast<size_t>(first_native_line + row)] : std::string{}};
        match.translation_result = layout.translation_result;
        match.layout_x = left;
        match.layout_y = y;
        match.layout_length = width;
        match.layout_left = true;
        match.layout_font_pixels = layout.font_pixels;
        match.layout_line_height_pixels = layout.line_height_pixels;
        match.layout_fixed_baseline = true;
        match.layout_native_clip = document_clip;
        match.layout_reflowed_paragraph = true;
        if (owns_line) match.layout_pixel_y = pixel_top - row * gps_->tile_pixel_y;
        auto foreground_rgb = [&](int foreground) {
            if (foreground < 0) foreground = document.foreground;
            const int palette = (foreground & 7) + ((foreground & 64) ? 8 : 0);
            return (gps_->uccolor[palette][0] << 16) |
                (gps_->uccolor[palette][1] << 8) | gps_->uccolor[palette][2];
        };
        match.layout_foreground_rgb = foreground_rgb(-1);
        if (owns_line) {
            const auto &colors = layout.line_foregrounds[static_cast<size_t>(target_line)];
            if (!colors.empty()) {
                match.layout_foreground_rgb = foreground_rgb(colors.front());
                if (std::any_of(colors.begin(), colors.end(), [&](int color) {
                        return foreground_rgb(color) != match.layout_foreground_rgb;
                    })) {
                    match.layout_glyph_foreground_rgb.reserve(colors.size());
                    for (int color : colors)
                        match.layout_glyph_foreground_rgb.push_back(foreground_rgb(color));
                }
            }
        }
        result.push_back(std::move(match));
    }
    native_knowledge_frame_ = {draws.front().document, logical_hash,
        left, top, first_native_line, height, geometry, result,
        layout.source_context, layout.resource_revision, layout.reusable};
    return result;
}

