struct AsciiPanelFrame {
    int left;
    int top;
    int right;
    int bottom;
};

static std::optional<AsciiPanelFrame> find_graphical_character_panel_frame(
        const graphicst &gps, int first_x, int last_x, int tab_y,
        bool require_classic_skin = false) {
    if (first_x < 0 || last_x > gps.dimx || first_x >= last_x ||
        tab_y < 0 || tab_y >= gps.dimy) return std::nullopt;
    // The active character frame can use init's current nine-slice skin,
    // not just graphicst's legacy border arrays. Share the same verified
    // skin/layer reader as the other native panels, especially when recovering
    // an already-open description whose old core discarded its captures.
    const NativePanelBorders borders(gps, require_classic_skin);
    // Enclose the whole health tab band. A neighbouring minimap or a single
    // tab's border cannot supply a connected pair of character-panel sides.
    int left = first_x - 1;
    while (left >= 0 && !borders.at(left, tab_y, 3)) --left;
    int right = last_x;
    while (right < gps.dimx && !borders.at(right, tab_y, 5)) ++right;
    if (left < 0 || right >= gps.dimx) return std::nullopt;
    for (int y = tab_y + 1; y < gps.dimy; ++y) {
        const bool bottom_left = borders.at(left, y, 6);
        const bool bottom_right = borders.at(right, y, 8);
        if (bottom_left && bottom_right) {
            for (int x = left + 1; x < right; ++x) {
                if (!borders.at(x, y, 7)) return std::nullopt;
            }
            return AsciiPanelFrame{left, tab_y, right, y};
        }
        if (!borders.at(left, y, 3) ||
            !borders.at(right, y, 5)) return std::nullopt;
    }
    return std::nullopt;
}

template <typename ReadChar>
static std::optional<AsciiPanelFrame> find_ascii_panel_frame(
        int first_x, int last_x, int tab_y, int columns, int rows,
        ReadChar read_char) {
    // Find the frame enclosing the complete character tab band, not a tab's
    // sloping ASCII outline or an adjacent embark button. Summary separators
    // meet the sides in T junctions; only bottom CORNERS close the pane.
    auto vertical = [](unsigned char ch) { return ch == 0xb3 || ch == 0xba; };
    int left = first_x - 1;
    while (left >= 0 && !vertical(read_char(left, tab_y))) --left;
    int right = last_x;
    while (right < columns && !vertical(read_char(right, tab_y))) ++right;
    if (left < 0 || right >= columns) return std::nullopt;
    auto horizontal = [&](int y) {
        for (int x = left + 1; x < right; ++x) {
            if (!is_cp437_box_drawing_byte(read_char(x, y))) return false;
        }
        return true;
    };
    int top = tab_y - 1;
    for (; top >= 0; --top) {
        const unsigned char l = read_char(left, top);
        const unsigned char r = read_char(right, top);
        if (!is_cp437_box_drawing_byte(l) || !is_cp437_box_drawing_byte(r))
            return std::nullopt;
        if ((l == 0xda || l == 0xc9 || l == 0xd5 || l == 0xd6) &&
            (r == 0xbf || r == 0xbb || r == 0xb7 || r == 0xb8) &&
            horizontal(top)) break;
    }
    if (top < 0) return std::nullopt;
    int bottom = tab_y + 1;
    for (; bottom < rows; ++bottom) {
        const unsigned char l = read_char(left, bottom);
        const unsigned char r = read_char(right, bottom);
        if (!is_cp437_box_drawing_byte(l) || !is_cp437_box_drawing_byte(r))
            return std::nullopt;
        if ((l == 0xc0 || l == 0xc8 || l == 0xd3 || l == 0xd4) &&
            (r == 0xd9 || r == 0xbc || r == 0xbd || r == 0xbe) &&
            horizontal(bottom)) break;
    }
    if (bottom >= rows) return std::nullopt;
    return AsciiPanelFrame{left, top, right, bottom};
}

// Overview has four independently verified summary bands. A native need or
// name can overwrite an outer ASCII edge without changing that panel's
// actual geometry. Recover only those cells whose current draw still proves
// the overwritten byte; other widgets keep the strict closed-frame reader.
template <typename ReadChar>
static std::optional<AsciiPanelFrame> find_character_overview_frame(
        const graphicst &gps, int first_x, int last_x, int tab_y,
        ReadChar read_char) {
    const auto settings = native_ui_settings();
    if (!settings || !settings->classic || first_x < 0 || last_x > gps.dimx ||
        first_x >= last_x || tab_y < 0 || tab_y >= gps.dimy) return std::nullopt;
    int content_top = tab_y + 1;
    const size_t tile = static_cast<size_t>(first_x) * gps.dimy + tab_y;
    const bool top_layer = native_ui_top_layer_at(gps, tile);
    const auto *flags = top_layer ? gps.screentexpos_top_flag : gps.screentexpos_flag;
    if (flags && (flags[tile] & (1u << 3))) ++content_top;
    const auto grid = find_character_summary_grid(gps, first_x, last_x, content_top);
    if (!grid) return std::nullopt;
    const int left = grid->left - 1, right = grid->right;
    if (left < 0 || right >= gps.dimx) return std::nullopt;
    const auto vertical = [](unsigned char ch) { return ch == 0xb3 || ch == 0xba; };
    if (!vertical(read_char(left, tab_y)) || !vertical(read_char(right, tab_y)))
        return std::nullopt;
    const auto horizontal = [&](int y) {
        for (int x = left + 1; x < right; ++x) {
            const auto ch = read_char(x, y);
            if (ch != 0xc4 && ch != 0xcd) return false;
        }
        return true;
    };
    const auto draws = captured_native_drawn_text_rows();
    const auto side = [&](int x, int y) {
        const unsigned char ch = read_char(x, y);
        if (vertical(ch) || ch == 0xc3 || ch == 0xb4 || ch == 0xcc || ch == 0xb9)
            return true;
        if (native_foreground_picture_at(gps, x, y) || native_item_action_at(gps, x, y))
            return false;
        for (const auto &draw : draws) {
            if (draw.y != y || draw.x <= left || draw.x >= right || draw.x > x ||
                draw.source.size() <= static_cast<size_t>(x - draw.x)) continue;
            bool current = true;
            for (int column = draw.x; column <= x; ++column) {
                const unsigned char actual = read_char(column, y);
                if ((actual ? actual : ' ') != static_cast<unsigned char>(
                        draw.source[static_cast<size_t>(column - draw.x)]) ||
                    native_foreground_picture_at(gps, column, y)) {
                    current = false;
                    break;
                }
            }
            if (current) return true;
        }
        return false;
    };
    int top = tab_y - 1;
    for (; top >= 0; --top) {
        const auto l = read_char(left, top), r = read_char(right, top);
        if ((l == 0xda || l == 0xc9 || l == 0xd5 || l == 0xd6) &&
            (r == 0xbf || r == 0xbb || r == 0xb7 || r == 0xb8) && horizontal(top)) break;
        if (!side(left, top) || !side(right, top)) return std::nullopt;
    }
    if (top < 0) return std::nullopt;
    int bottom = tab_y + 1;
    for (; bottom < gps.dimy; ++bottom) {
        const auto l = read_char(left, bottom), r = read_char(right, bottom);
        if ((l == 0xc0 || l == 0xc8 || l == 0xd3 || l == 0xd4) &&
            (r == 0xd9 || r == 0xbc || r == 0xbd || r == 0xbe) && horizontal(bottom)) break;
        if (!side(left, bottom) || !side(right, bottom)) return std::nullopt;
    }
    if (bottom >= gps.dimy || bottom <= grid->bottom) return std::nullopt;
    return AsciiPanelFrame{left, top, right, bottom};
}

