static bool help_background_covered(const Match &match, int x, int y) {
    if (match.native_dfhack_foreground) return false;
    if (match.native_help_occluder) {
        const auto &frame = *match.native_help_occluder;
        if (x >= frame.x && x < frame.x + frame.w &&
            y >= frame.y && y < frame.y + frame.h) return true;
    }
    if (g_native_toolbar_tooltip && g_native_toolbar_tooltip->widget_frame &&
        (match.rule == kToolbarTooltipBodyRule || match.rule == kToolbarTooltipKeyRule) &&
        std::any_of(g_native_toolbar_tooltip->occlusions.begin(),
            g_native_toolbar_tooltip->occlusions.end(), [&](const SDL_Rect &box) {
                return x >= box.x && x < box.x + box.w && y >= box.y && y < box.y + box.h;
            })) return true;
    if (!match.native_help_background_frames) return false;
    return std::any_of(match.native_help_background_frames->begin(),
        match.native_help_background_frames->end(), [&](const SDL_Rect &frame) {
            return x >= frame.x && x < frame.x + frame.w &&
                y >= frame.y && y < frame.y + frame.h;
        });
}

