                constexpr uint32_t top_half = 1u << 3;
                constexpr uint32_t bottom_half = 1u << 4;
                const auto caption_half = [&](int row_y) {
                    if (choice_caption_right(row_y) < end) return UINT32_MAX;
                    uint32_t half = UINT32_MAX;
                    for (int x = first; x < end; ++x) {
                        if (context[row_y][x] == ' ') continue;
                        bool top = false;
                        cell_at(x, row_y, &top);
                        const auto *flags = top
                            ? gps_->screentexpos_top_flag : gps_->screentexpos_flag;
                        const uint32_t current = flags
                            ? flags[static_cast<size_t>(x) * gps_->dimy + row_y] &
                                (top_half | bottom_half) : 0;
                        if (current == (top_half | bottom_half) ||
                            (half != UINT32_MAX && half != current)) return UINT32_MAX;
                        half = current;
                    }
                    return half;
                };
                // Native padding between separately drawn words need not
                // have a font flag. Only actual glyphs define the two halves
                // of one caption; they never become two Chinese line slots.
