static bool is_embark_wear_item_source(std::string_view raw) {
    const std::string source = lower(trim(std::string(raw)));
    static constexpr auto nouns = std::to_array<std::string_view>({
        "breastplate", "breastplates", "mail shirt", "mail shirts",
        "armor", "coat", "coats", "shirt", "shirts", "cloak", "cloaks",
        "tunic", "tunics", "toga", "togas", "cape", "capes", "vest",
        "vests", "dress", "dresses", "robe", "robes",
        "helm", "helms", "cap", "caps", "hood", "hoods", "turban",
        "turbans", "mask", "masks", "head veil", "head veils",
        "face veil", "face veils", "headscarf", "headscarves",
        "gauntlet", "gauntlets", "glove", "gloves", "mitten", "mittens",
        "shoe", "shoes", "high boot", "high boots", "low boot",
        "low boots", "sandal", "sandals", "chausse", "chausses", "sock",
        "socks", "trousers", "greaves", "leggings", "loincloth",
        "loincloths", "thong", "thongs", "skirt", "skirts", "braies",
    });
    return std::any_of(nouns.begin(), nouns.end(), [&](std::string_view noun) {
        return source == noun ||
            (source.size() > noun.size() && source.ends_with(noun) &&
             source[source.size() - noun.size() - 1] == ' ');
    });
}

